  var D20_TOPIC_REGISTRATIONS = [{"id":"grammar-d20-starter-be-positive","titleEn":"I am / You are / He is (Positive)","titlePs":"زه یم / ته یې / هغه دی (مثبت)","levelNumber":null,"acceptedLevelId":"starter","branchId":"be-verb","subbranchId":"am-is-are-positive","masteryConceptId":"grammar-concept-am-is-are-positive","prerequisites":[],"wizardSessionId":"grammar-d20-starter-be-positive-wiz","testSessionId":"grammar-d20-starter-be-positive-test","blocks":[{"type":"explanation","titleEn":"I am / You are / He is (Positive)","en":"Use am with I. Use are with you/we/they. Use is with he/she/it.","ps":"د \"زه\" سره am کاروو. د \"ته/موږ/دوی\" سره are کاروو. د \"هغه/هغه/دا\" سره is کاروو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I am a student.","ps":"زه زده کوونکی یم."},{"en":"You are my friend.","ps":"ته زما ملګری یې."},{"en":"He is a teacher.","ps":"هغه ښوونکی دی."},{"en":"She is happy.","ps":"هغه خوشحاله ده."},{"en":"It is a book.","ps":"دا یوه کتاب دی."},{"en":"We are at school.","ps":"موږ په ښوونځي کې یو."},{"en":"They are children.","ps":"دوی ماشومان دي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I is a student. | Right: I am a student. | Use am with I, never is or are.","ps":"د \"زه\" سره تل am کارول کیږي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-starter-be-negative","titleEn":"am/is/are Negatives","titlePs":"am/is/are نفی","levelNumber":null,"acceptedLevelId":"starter","branchId":"be-verb","subbranchId":"am-is-are-negative","masteryConceptId":"grammar-concept-am-is-are-negative","prerequisites":["grammar-d20-starter-be-positive"],"wizardSessionId":"grammar-d20-starter-be-negative-wiz","testSessionId":"grammar-d20-starter-be-negative-test","blocks":[{"type":"explanation","titleEn":"am/is/are Negatives","en":"Add not after am/is/are to make a negative sentence.","ps":"د نفي جملې لپاره am/is/are وروسته not زیاتوو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I am not tired.","ps":"زه ستړی نه یم."},{"en":"You are not late.","ps":"ته ناوخته نه یې."},{"en":"He is not here.","ps":"هغه دلته نه دی."},{"en":"She is not a doctor.","ps":"هغه ډاکټره نه ده."},{"en":"It is not cold.","ps":"دا سړه نه ده."},{"en":"We are not ready.","ps":"موږ چمتو نه یو."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I not am tired. | Right: I am not tired. | not comes AFTER the be-verb, not before.","ps":"not تل د be-فعل وروسته راځي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-starter-be-questions","titleEn":"am/is/are Yes/No Questions","titlePs":"am/is/are پوښتنې","levelNumber":null,"acceptedLevelId":"starter","branchId":"be-verb","subbranchId":"am-is-are-questions","masteryConceptId":"grammar-concept-am-is-are-questions","prerequisites":["grammar-d20-starter-be-negative"],"wizardSessionId":"grammar-d20-starter-be-questions-wiz","testSessionId":"grammar-d20-starter-be-questions-test","blocks":[{"type":"explanation","titleEn":"am/is/are Yes/No Questions","en":"Move am/is/are to the start of the sentence to ask a question. Answer with Yes, I am. / No, I am not.","ps":"د پوښتنې لپاره am/is/are جملې پیل ته وړو. ځواب: هو، زه یم. / نه، زه نه یم."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Am I late?","ps":"آیا زه ناوخته یم؟"},{"en":"Are you a student?","ps":"آیا ته زده کوونکی یې؟"},{"en":"Is he your brother?","ps":"آیا هغه ستا ورور دی؟"},{"en":"Is she at home?","ps":"آیا هغه په کور کې ده؟"},{"en":"Are we late?","ps":"آیا موږ ناوخته یو؟"},{"en":"Are they ready?","ps":"آیا دوی چمتو دي؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: He is your brother? | Right: Is he your brother? | Yes/No questions need the be-verb FIRST.","ps":"د هو/نه پوښتنو کې be-فعل باید لومړی راشي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-starter-this-that","titleEn":"this / that / these / those","titlePs":"دا / هغه / دا (جمع) / هغه (جمع)","levelNumber":null,"acceptedLevelId":"starter","branchId":"demonstratives","subbranchId":"this-that-these-those","masteryConceptId":"grammar-concept-this-that-these-those","prerequisites":[],"wizardSessionId":"grammar-d20-starter-this-that-wiz","testSessionId":"grammar-d20-starter-this-that-test","blocks":[{"type":"explanation","titleEn":"this / that / these / those","en":"this/that = one thing (singular). these/those = more than one thing (plural). this/these = near. that/those = far.","ps":"this/that = یوه شی لپاره. these/those = ډېرو شیانو لپاره. this/these = نږدې شی. that/those = لرې شی."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"This is my pen.","ps":"دا زما قلم دی."},{"en":"That is your book.","ps":"هغه ستا کتاب دی."},{"en":"These are my pens.","ps":"دا زما قلمونه دي."},{"en":"Those are your books.","ps":"هغه ستا کتابونه دي."},{"en":"This is a cat.","ps":"دا یوه پیشو ده."},{"en":"Those are birds.","ps":"هغه مرغان دي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: These is my pens. | Right: These are my pens. | these/those always take are, never is.","ps":"these/those تل are کاروي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-starter-singular-plural","titleEn":"Singular and Plural Awareness","titlePs":"واحد او جمع پیژندنه","levelNumber":null,"acceptedLevelId":"starter","branchId":"nouns","subbranchId":"singular-plural-awareness","masteryConceptId":"grammar-concept-singular-plural-awareness","prerequisites":[],"wizardSessionId":"grammar-d20-starter-singular-plural-wiz","testSessionId":"grammar-d20-starter-singular-plural-test","blocks":[{"type":"explanation","titleEn":"Singular and Plural Awareness","en":"One thing = singular (book). More than one = plural, usually add -s (books).","ps":"یو شی = واحد (کتاب). له یو څخه ډېر = جمع، معمولا -s زیاتوو (کتابونه)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"one book, two books","ps":"یو کتاب، دوه کتابونه"},{"en":"one cat, three cats","ps":"یوه پیشو، درې پیشوګانې"},{"en":"one pen, five pens","ps":"یو قلم، پنځه قلمونه"},{"en":"one girl, four girls","ps":"یوه انجلۍ، څلور انجونې"},{"en":"one apple, six apples","ps":"یو مڼه، شپږ مڼې"},{"en":"one chair, two chairs","ps":"یوه څوکۍ، دوه څوکۍ"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: two book | Right: two books | Numbers above one need the plural -s.","ps":"له یو څخه ډېر شمېر -s ته اړتیا لري."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-starter-adj-with-be","titleEn":"Basic Adjectives with be","titlePs":"د be سره بنسټیز صفتونه","levelNumber":null,"acceptedLevelId":"starter","branchId":"adjectives","subbranchId":"basic-adjectives-with-be","masteryConceptId":"grammar-concept-basic-adjectives-with-be","prerequisites":["grammar-d20-starter-be-positive"],"wizardSessionId":"grammar-d20-starter-adj-with-be-wiz","testSessionId":"grammar-d20-starter-adj-with-be-test","blocks":[{"type":"explanation","titleEn":"Basic Adjectives with be","en":"Adjectives describe nouns. With be, put the adjective after am/is/are.","ps":"صفتونه نومونه بیانوي. د be سره، صفت د am/is/are وروسته راځي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The book is big.","ps":"کتاب لوی دی."},{"en":"I am happy.","ps":"زه خوشحاله یم."},{"en":"She is tall.","ps":"هغه لوړه ده."},{"en":"They are small.","ps":"دوی کوچني دي."},{"en":"The tea is hot.","ps":"چای ګرم دی."},{"en":"We are tired.","ps":"موږ ستړي یو."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The book big is. | Right: The book is big. | The adjective goes AFTER the be-verb.","ps":"صفت د be-فعل وروسته راځي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-starter-classroom-commands","titleEn":"Simple Classroom Commands","titlePs":"ساده د ټولګي امرونه","levelNumber":null,"acceptedLevelId":"starter","branchId":"imperatives","subbranchId":"classroom-commands","masteryConceptId":"grammar-concept-classroom-commands","prerequisites":[],"wizardSessionId":"grammar-d20-starter-classroom-commands-wiz","testSessionId":"grammar-d20-starter-classroom-commands-test","blocks":[{"type":"explanation","titleEn":"Simple Classroom Commands","en":"Commands use the base verb with no subject: Open, Close, Listen, Look, Write.","ps":"امرونه د اصلي فعل سره پرته له فاعل کارول کیږي: پرانیزه، وتړه، واوره، وګوره، ولیکه."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Open your book.","ps":"خپل کتاب پرانیزه."},{"en":"Close the door.","ps":"دروازه وتړه."},{"en":"Listen carefully.","ps":"په دقت سره واوره."},{"en":"Look at the board.","ps":"تختې ته وګوره."},{"en":"Write your name.","ps":"خپل نوم ولیکه."},{"en":"Sit down, please.","ps":"مهرباني وکړئ کښېنئ."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: You open your book. | Right: Open your book. | Commands do not use a subject like you.","ps":"امرونه فاعل نه کاروي لکه \"ته\"."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-basic-can-cannot","titleEn":"can / cannot (Basic Ability)","titlePs":"کولی شم / نشم کولی (بنسټیز)","levelNumber":null,"acceptedLevelId":"basic","branchId":"modals","subbranchId":"can-cannot-basic","masteryConceptId":"grammar-concept-can-cannot-basic","prerequisites":[],"wizardSessionId":"grammar-d20-basic-can-cannot-wiz","testSessionId":"grammar-d20-basic-can-cannot-test","blocks":[{"type":"explanation","titleEn":"can / cannot (Basic Ability)","en":"Use can + base verb to show ability. Use cannot (can't) for the negative.","ps":"د توان ښودلو لپاره can + اصلي فعل کاروو. د نفي لپاره cannot (can't) کاروو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I can swim.","ps":"زه لامبل کولی شم."},{"en":"She can drive.","ps":"هغه موټر چلولی شي."},{"en":"We cannot fly.","ps":"موږ الوتلی نشو."},{"en":"He can cook well.","ps":"هغه ښه پخول کولی شي."},{"en":"They cannot come today.","ps":"دوی نن نشي راتلی."},{"en":"You can speak English.","ps":"ته انګلیسي ویلی شې."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: She cans drive. | Right: She can drive. | can never adds -s, even with he/she/it.","ps":"can هیڅکله -s نه اخلي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-basic-there-is-are","titleEn":"there is / there are","titlePs":"شته دی / شته دي","levelNumber":null,"acceptedLevelId":"basic","branchId":"existentials","subbranchId":"there-is-there-are","masteryConceptId":"grammar-concept-there-is-there-are","prerequisites":[],"wizardSessionId":"grammar-d20-basic-there-is-are-wiz","testSessionId":"grammar-d20-basic-there-is-are-test","blocks":[{"type":"explanation","titleEn":"there is / there are","en":"there is + singular noun. there are + plural noun. Used to say something exists.","ps":"there is + واحد نوم. there are + جمع نوم. د یو شي شتون ښودلو لپاره کارول کیږي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"There is a cat on the roof.","ps":"د چت پر سر یوه پیشو شته."},{"en":"There are three books on the table.","ps":"په میز باندې درې کتابونه شته دي."},{"en":"There is a problem.","ps":"یوه ستونزه شته ده."},{"en":"There are many students.","ps":"ډېر زده کوونکي شته دي."},{"en":"There is no water.","ps":"اوبه نشته."},{"en":"There are two doors.","ps":"دوه دروازې شته دي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: There is three books. | Right: There are three books. | Plural nouns need there are, not there is.","ps":"د جمع نومونو سره there are کارول کیږي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-basic-frequency-adverbs","titleEn":"Frequency Adverbs (always, usually, often, sometimes, never)","titlePs":"د بیا بیا کیدو قیدونه","levelNumber":null,"acceptedLevelId":"basic","branchId":"adverbs","subbranchId":"frequency-adverbs-basic","masteryConceptId":"grammar-concept-frequency-adverbs-basic","prerequisites":[],"wizardSessionId":"grammar-d20-basic-frequency-adverbs-wiz","testSessionId":"grammar-d20-basic-frequency-adverbs-test","blocks":[{"type":"explanation","titleEn":"Frequency Adverbs (always, usually, often, sometimes, never)","en":"Frequency adverbs go before the main verb, but after am/is/are.","ps":"د بیا بیا کیدو قیدونه د اصلي فعل مخکې راځي، خو د am/is/are وروسته."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I always drink tea.","ps":"زه تل چای څښم."},{"en":"She usually walks to school.","ps":"هغه معمولا ښوونځي ته پیاده ځي."},{"en":"We often visit our grandmother.","ps":"موږ اکثرا نیکه ته ورځو."},{"en":"He sometimes forgets his book.","ps":"هغه کله ناکله خپل کتاب هیروي."},{"en":"They never eat meat.","ps":"دوی هیڅکله غوښه نه خوري."},{"en":"I am always happy.","ps":"زه تل خوشحاله یم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I drink always tea. | Right: I always drink tea. | The adverb goes before the main verb, not after.","ps":"قید د اصلي فعل مخکې راځي، نه وروسته."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-basic-prepositions-time-place","titleEn":"Basic Prepositions of Time and Place (in, on, at)","titlePs":"د وخت او ځای بنسټیز حرفونه","levelNumber":null,"acceptedLevelId":"basic","branchId":"prepositions","subbranchId":"time-place-prepositions-basic","masteryConceptId":"grammar-concept-time-place-prepositions-basic","prerequisites":[],"wizardSessionId":"grammar-d20-basic-prepositions-time-place-wiz","testSessionId":"grammar-d20-basic-prepositions-time-place-test","blocks":[{"type":"explanation","titleEn":"Basic Prepositions of Time and Place (in, on, at)","en":"in = months/years/rooms. on = days/dates/surfaces. at = clock times/specific points.","ps":"in = میاشتې/کلونه/خونې. on = ورځې/نیټې/سطحې. at = ساعتونه/ځانګړي ځایونه."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I was born in 2005.","ps":"زه په ۲۰۰۵ کال کې زیږیدلی یم."},{"en":"The class is on Monday.","ps":"ټولګی د دوشنبې په ورځ دی."},{"en":"We meet at 5 o'clock.","ps":"موږ په ۵ بجو ملاقات کوو."},{"en":"The book is on the table.","ps":"کتاب په میز باندې دی."},{"en":"She lives in Kabul.","ps":"هغه په کابل کې ژوند کوي."},{"en":"I will see you at the market.","ps":"زه به تا په بازار کې وګورم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I was born on 2005. | Right: I was born in 2005. | Use in with years, not on.","ps":"د کلونو سره in کارول کیږي، نه on."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-basic-adj-noun-order","titleEn":"Adjective + Noun Order","titlePs":"د صفت + نوم ترتیب","levelNumber":null,"acceptedLevelId":"basic","branchId":"adjectives","subbranchId":"adjective-noun-order-basic","masteryConceptId":"grammar-concept-adjective-noun-order-basic","prerequisites":[],"wizardSessionId":"grammar-d20-basic-adj-noun-order-wiz","testSessionId":"grammar-d20-basic-adj-noun-order-test","blocks":[{"type":"explanation","titleEn":"Adjective + Noun Order","en":"In English, the adjective comes BEFORE the noun it describes.","ps":"په انګلیسي کې، صفت د هغه نوم مخکې راځي چې بیانوي یې."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"a big house","ps":"یو لوی کور"},{"en":"a red car","ps":"یو سور موټر"},{"en":"an old man","ps":"یو زوړ سړی"},{"en":"a beautiful garden","ps":"یو ښکلی باغ"},{"en":"three small dogs","ps":"درې کوچني سپي"},{"en":"a difficult question","ps":"یوه ستونزمنه پوښتنه"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: a house big | Right: a big house | The adjective must come before the noun, not after.","ps":"صفت باید د نوم مخکې راشي، نه وروسته."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-basic-countable-intro","titleEn":"Countable and Uncountable Nouns (Introduction)","titlePs":"د شمېرلو وړ او نه وړ نومونه (پېژندنه)","levelNumber":null,"acceptedLevelId":"basic","branchId":"nouns","subbranchId":"countable-uncountable-intro","masteryConceptId":"grammar-concept-countable-uncountable-intro","prerequisites":[],"wizardSessionId":"grammar-d20-basic-countable-intro-wiz","testSessionId":"grammar-d20-basic-countable-intro-test","blocks":[{"type":"explanation","titleEn":"Countable and Uncountable Nouns (Introduction)","en":"Countable nouns can be counted (one book, two books). Uncountable nouns cannot (water, rice, money).","ps":"د شمېرلو وړ نومونه شمېرل کیدی شي (یو کتاب، دوه کتابونه). د شمېرلو نه وړ نومونه نشي شمېرل کیدی (اوبه، وریجې، پیسې)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I have two books.","ps":"زه دوه کتابونه لرم."},{"en":"I need some water.","ps":"زه یو څه اوبو ته اړتیا لرم."},{"en":"She has three apples.","ps":"هغه درې مڼې لري."},{"en":"We need some rice.","ps":"موږ یو څه وریجو ته اړتیا لرو."},{"en":"He has one dollar.","ps":"هغه یو ډالر لري."},{"en":"I don't have much money.","ps":"زه ډېرې پیسې نه لرم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I need a water. | Right: I need some water. | Uncountable nouns like water do not take a/an or a plural -s.","ps":"اوبه لکه نور نه شمېرل کیدونکي نومونه a/an یا -s نه اخلي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-past-simple-positive","titleEn":"Past Simple: Positive (Regular Verbs)","titlePs":"تېر ساده مهال: مثبت (منظم افعال)","levelNumber":null,"acceptedLevelId":"beginner","branchId":"tenses","subbranchId":"past-simple-positive","masteryConceptId":"grammar-concept-past-simple-positive","prerequisites":["grammar-d20-basic-can-cannot"],"wizardSessionId":"grammar-d20-beginner-past-simple-positive-wiz","testSessionId":"grammar-d20-beginner-past-simple-positive-test","blocks":[{"type":"explanation","titleEn":"Past Simple: Positive (Regular Verbs)","en":"Add -ed to regular verbs to talk about finished past actions.","ps":"د تېرو پای ته رسیدلو کړنو لپاره منظم افعالو ته -ed زیاتوو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I walked to school yesterday.","ps":"زه پرون ښوونځي ته پیاده لاړم."},{"en":"She played football last week.","ps":"هغې تیره اونۍ فوټبال وکاوه."},{"en":"We watched a movie.","ps":"موږ یو فلم ولید."},{"en":"He worked all day.","ps":"هغه ټوله ورځ کار وکړ."},{"en":"They visited their uncle.","ps":"دوی د خپل تره کره لاړل."},{"en":"I studied English last night.","ps":"زه پرون شپه انګلیسي ولوستله."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I walk to school yesterday. | Right: I walked to school yesterday. | Past time words like yesterday need the past tense verb.","ps":"د پرون په څېر تېر وخت کلمې د تېر مهال فعل غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-past-simple-irregular","titleEn":"Past Simple: Common Irregular Verbs","titlePs":"تېر ساده مهال: مشهور غیر منظم افعال","levelNumber":null,"acceptedLevelId":"beginner","branchId":"tenses","subbranchId":"past-simple-irregular","masteryConceptId":"grammar-concept-past-simple-irregular","prerequisites":["grammar-d20-beginner-past-simple-positive"],"wizardSessionId":"grammar-d20-beginner-past-simple-irregular-wiz","testSessionId":"grammar-d20-beginner-past-simple-irregular-test","blocks":[{"type":"explanation","titleEn":"Past Simple: Common Irregular Verbs","en":"Irregular verbs do not add -ed. They change form completely: go→went, see→saw, eat→ate.","ps":"غیر منظم افعال -ed نه اخلي. بشپړ بدلون کوي: go→went, see→saw, eat→ate."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I went to the market.","ps":"زه بازار ته لاړم."},{"en":"She saw her friend.","ps":"هغې خپل ملګری ولید."},{"en":"We ate rice for lunch.","ps":"موږ د غرمې ډوډۍ لپاره وریجې وخوړلې."},{"en":"He came home late.","ps":"هغه ناوخته کور ته راغی."},{"en":"They had a good day.","ps":"دوی ښه ورځ لرله."},{"en":"I bought a new phone.","ps":"زه یو نوی ټیلیفون واخیستم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I goed to the market. | Right: I went to the market. | go is irregular — it becomes went, never goed.","ps":"go غیر منظم دی، went کیږي نه goed."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-past-simple-negative-questions","titleEn":"Past Simple: Negative and Questions","titlePs":"تېر ساده مهال: نفي او پوښتنې","levelNumber":null,"acceptedLevelId":"beginner","branchId":"tenses","subbranchId":"past-simple-negative-questions","masteryConceptId":"grammar-concept-past-simple-negative-questions","prerequisites":["grammar-d20-beginner-past-simple-irregular"],"wizardSessionId":"grammar-d20-beginner-past-simple-negative-questions-wiz","testSessionId":"grammar-d20-beginner-past-simple-negative-questions-test","blocks":[{"type":"explanation","titleEn":"Past Simple: Negative and Questions","en":"Negative: did not (didn't) + base verb. Question: Did + subject + base verb?","ps":"نفي: did not (didn't) + اصلي فعل. پوښتنه: Did + فاعل + اصلي فعل؟"},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I did not go to school.","ps":"زه ښوونځي ته نه یم تللی."},{"en":"She didn't call me.","ps":"هغې ما ته زنګ ونه وهه."},{"en":"Did you finish your homework?","ps":"آیا خپل کورنی کار دې بشپړ کړ؟"},{"en":"Did he come to the party?","ps":"آیا هغه غونډې ته راغی؟"},{"en":"We didn't eat breakfast.","ps":"موږ ناری ونه خوړله."},{"en":"Did they arrive on time?","ps":"آیا دوی په وخت راورسیدل؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Did you went there? | Right: Did you go there? | After did, use the BASE verb, not the past form.","ps":"د did وروسته اصلي فعل کارول کیږي، نه تېر ډول."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-future-will","titleEn":"Future: will","titlePs":"راتلونکی مهال: will","levelNumber":null,"acceptedLevelId":"beginner","branchId":"tenses","subbranchId":"future-will","masteryConceptId":"grammar-concept-future-will","prerequisites":["grammar-d20-beginner-past-simple-negative-questions"],"wizardSessionId":"grammar-d20-beginner-future-will-wiz","testSessionId":"grammar-d20-beginner-future-will-test","blocks":[{"type":"explanation","titleEn":"Future: will","en":"Use will + base verb for future predictions, promises, or spontaneous decisions.","ps":"د راتلونکو وړاندوینو، ژمنو یا سملاسي پرېکړو لپاره will + اصلي فعل کاروو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I will call you tomorrow.","ps":"زه به سبا تاته زنګ ووهم."},{"en":"It will rain tonight.","ps":"نن شپه به باران وشي."},{"en":"She will help you.","ps":"هغه به تاسره مرسته وکړي."},{"en":"We will finish soon.","ps":"موږ به ژر بشپړ کړو."},{"en":"They will not come.","ps":"دوی به رانشي."},{"en":"Will you join us?","ps":"آیا به له موږ سره یوځای شې؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I will to call you. | Right: I will call you. | Never use to after will.","ps":"د will وروسته هیڅکله to نه راځي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-future-going-to","titleEn":"Future: going to","titlePs":"راتلونکی مهال: going to","levelNumber":null,"acceptedLevelId":"beginner","branchId":"tenses","subbranchId":"future-going-to","masteryConceptId":"grammar-concept-future-going-to","prerequisites":["grammar-d20-beginner-future-will"],"wizardSessionId":"grammar-d20-beginner-future-going-to-wiz","testSessionId":"grammar-d20-beginner-future-going-to-test","blocks":[{"type":"explanation","titleEn":"Future: going to","en":"Use am/is/are + going to + base verb for plans already decided.","ps":"د مخکې پرېکړل شویو پلانونو لپاره am/is/are + going to + اصلي فعل کاروو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I am going to study tonight.","ps":"زه به نن شپه ولولم."},{"en":"She is going to visit her family.","ps":"هغه به خپلې کورنۍ ته ورځي."},{"en":"We are going to travel next month.","ps":"موږ به بله میاشت سفر وکړو."},{"en":"He is going to buy a car.","ps":"هغه به موټر واخلي."},{"en":"They are not going to come.","ps":"دوی رانه ځي."},{"en":"Are you going to help me?","ps":"آیا به له ما سره مرسته وکړې؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I going to study. | Right: I am going to study. | Do not forget am/is/are before going to.","ps":"د going to مخکې am/is/are مه هیروئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-object-pronouns","titleEn":"Object Pronouns (me, you, him, her, it, us, them)","titlePs":"د مفعول ضمیرونه","levelNumber":null,"acceptedLevelId":"beginner","branchId":"pronouns","subbranchId":"object-pronouns-beginner","masteryConceptId":"grammar-concept-object-pronouns-beginner","prerequisites":[],"wizardSessionId":"grammar-d20-beginner-object-pronouns-wiz","testSessionId":"grammar-d20-beginner-object-pronouns-test","blocks":[{"type":"explanation","titleEn":"Object Pronouns (me, you, him, her, it, us, them)","en":"Object pronouns replace the noun receiving the action, placed after the verb.","ps":"د مفعول ضمیرونه هغه نوم ځای ناستی کوي چې کړنه ترلاسه کوي، د فعل وروسته راځي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"She loves him.","ps":"هغې هغه سره مینه لري."},{"en":"I saw her yesterday.","ps":"زه پرون هغه ولیدله."},{"en":"Give it to me.","ps":"دا ماته راکړه."},{"en":"We helped them.","ps":"موږ له دوی سره مرسته وکړه."},{"en":"Please call us tonight.","ps":"مهرباني وکړئ نن شپه موږ ته زنګ ووهئ."},{"en":"He knows you well.","ps":"هغه تاسو ښه پیژني."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: She loves he. | Right: She loves him. | After a verb, use the object form (him), not the subject form (he).","ps":"د فعل وروسته د مفعول بڼه (him) کارول کیږي، نه فاعل بڼه (he)."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-comparatives-superlatives","titleEn":"Comparatives and Superlatives","titlePs":"د پرتلې او ترټولو زیات درجې","levelNumber":null,"acceptedLevelId":"beginner","branchId":"adjectives","subbranchId":"comparatives-superlatives","masteryConceptId":"grammar-concept-comparatives-superlatives","prerequisites":["grammar-d20-basic-adj-noun-order"],"wizardSessionId":"grammar-d20-beginner-comparatives-superlatives-wiz","testSessionId":"grammar-d20-beginner-comparatives-superlatives-test","blocks":[{"type":"explanation","titleEn":"Comparatives and Superlatives","en":"Comparative (-er/more) compares two things. Superlative (-est/most) compares three or more.","ps":"د پرتلې درجه (-er/more) دوه شیان پرتله کوي. تر ټولو زیاته درجه (-est/most) درې یا ډېر شیان پرتله کوي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"This book is bigger than that one.","ps":"دا کتاب له هغه څخه لوی دی."},{"en":"She is the tallest in her class.","ps":"هغه په خپل ټولګي کې تر ټولو لوړه ده."},{"en":"This test is more difficult.","ps":"دا ازموینه ډېره ستونزمنه ده."},{"en":"He is the most intelligent student.","ps":"هغه تر ټولو هوښیار زده کوونکی دی."},{"en":"My house is smaller than yours.","ps":"زما کور له ستا څخه کوچنی دی."},{"en":"This is the best restaurant in the city.","ps":"دا په ښار کې تر ټولو ښه رستورانت دی."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: more bigger | Right: bigger | Do not use more with an -er adjective — choose one form only.","ps":"د -er صفت سره more مه کاروئ، یوازې یوه بڼه وکاروئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-beginner-conjunctions","titleEn":"Conjunctions: and, but, because, so","titlePs":"د نښلونکو کلماتو: and, but, because, so","levelNumber":null,"acceptedLevelId":"beginner","branchId":"connectors","subbranchId":"conjunctions-and-but-because-so","masteryConceptId":"grammar-concept-conjunctions-and-but-because-so","prerequisites":[],"wizardSessionId":"grammar-d20-beginner-conjunctions-wiz","testSessionId":"grammar-d20-beginner-conjunctions-test","blocks":[{"type":"explanation","titleEn":"Conjunctions: and, but, because, so","en":"and joins similar ideas. but shows contrast. because gives a reason. so shows a result.","ps":"and ورته نظرونه نښلوي. but توپیر ښیي. because دلیل ورکوي. so پایله ښیي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I like tea and coffee.","ps":"زه چای او قهوه خوښوم."},{"en":"She is tired but happy.","ps":"هغه ستړې خو خوشحاله ده."},{"en":"I stayed home because it rained.","ps":"زه کور کې پاتې شوم ځکه چې باران وشو."},{"en":"He was late, so he ran.","ps":"هغه ناوخته و، نو منډه یې کړه."},{"en":"We studied hard and passed the exam.","ps":"موږ سخت ولوستل او ازموینه مو تیره کړه."},{"en":"She wanted to go but could not.","ps":"هغه غوښتل لاړه شي خو ونشوای."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I stayed home so it rained. | Right: I stayed home because it rained. | because gives the reason; so gives the result — they are not interchangeable.","ps":"because دلیل ورکوي؛ so پایله ورکوي، دواړه یو د بل ځای نه نیسي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-past-continuous","titleEn":"Past Continuous","titlePs":"تېر دوامداره مهال","levelNumber":null,"acceptedLevelId":"elementary","branchId":"tenses","subbranchId":"past-continuous","masteryConceptId":"grammar-concept-past-continuous","prerequisites":["grammar-d20-beginner-past-simple-irregular"],"wizardSessionId":"grammar-d20-elementary-past-continuous-wiz","testSessionId":"grammar-d20-elementary-past-continuous-test","blocks":[{"type":"explanation","titleEn":"Past Continuous","en":"was/were + verb-ing describes an action in progress at a specific past moment.","ps":"was/were + verb-ing هغه کړنه بیانوي چې د تېر مهال یو ټاکلي شیبه کې روانه وه."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I was studying at 8pm.","ps":"زه د ۸ بجو ولولم."},{"en":"They were playing football.","ps":"دوی فوټبال کاوه."},{"en":"She was cooking when I arrived.","ps":"کله چې زه ورسیدم هغه پخول کاوه."},{"en":"We were watching TV all evening.","ps":"موږ ټوله ماښام ټلویزیون ولید."},{"en":"He was not listening.","ps":"هغه نه اورېده."},{"en":"What were you doing at noon?","ps":"د غرمې مهال دې څه کول؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I was study. | Right: I was studying. | Past continuous needs the -ing form after was/were.","ps":"تېر دوامداره مهال د was/were وروسته -ing بڼه غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-past-simple-vs-continuous","titleEn":"Past Simple vs Past Continuous","titlePs":"تېر ساده مهال بمقابل تېر دوامداره مهال","levelNumber":null,"acceptedLevelId":"elementary","branchId":"tenses","subbranchId":"past-simple-vs-continuous","masteryConceptId":"grammar-concept-past-simple-vs-continuous","prerequisites":["grammar-d20-elementary-past-continuous"],"wizardSessionId":"grammar-d20-elementary-past-simple-vs-continuous-wiz","testSessionId":"grammar-d20-elementary-past-simple-vs-continuous-test","blocks":[{"type":"explanation","titleEn":"Past Simple vs Past Continuous","en":"Use past continuous for the longer background action, and past simple for the shorter interrupting action.","ps":"د اوږدې شاليدي کړنې لپاره تېر دوامداره مهال، او د لنډې مداخلوونکې کړنې لپاره تېر ساده مهال کاروو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I was sleeping when the phone rang.","ps":"کله چې ټیلیفون وږغیده زه ویدم وم."},{"en":"She was walking home when it started to rain.","ps":"کله چې باران پیل شو هغه کور ته روانه وه."},{"en":"While we were eating, the lights went out.","ps":"پداسې حال کې چې موږ خوړل کول، رڼاوي بند شوه."},{"en":"He saw an accident while he was driving.","ps":"د موټر چلولو پر مهال هغه یو پیښه ولیدله."},{"en":"They were talking when the teacher entered.","ps":"کله چې ښوونکی راننوت دوی خبرې کولې."},{"en":"I finished my work while she was resting.","ps":"زه خپل کار پای ته ورساوه پداسې حال کې چې هغه ارامه."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I slept when the phone was ringing. | Right: I was sleeping when the phone rang. | The interrupting action uses past simple; the background action uses past continuous.","ps":"مداخلوونکې کړنه تېر ساده مهال کاروي؛ شاليدي کړنه تېر دوامداره مهال کاروي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-present-perfect-intro","titleEn":"Present Perfect: Introduction","titlePs":"اوسنی بشپړ مهال: پېژندنه","levelNumber":null,"acceptedLevelId":"elementary","branchId":"tenses","subbranchId":"present-perfect-introduction","masteryConceptId":"grammar-concept-present-perfect-introduction","prerequisites":["grammar-d20-elementary-past-simple-vs-continuous"],"wizardSessionId":"grammar-d20-elementary-present-perfect-intro-wiz","testSessionId":"grammar-d20-elementary-present-perfect-intro-test","blocks":[{"type":"explanation","titleEn":"Present Perfect: Introduction","en":"have/has + past participle connects the past to the present — for experiences and results that matter now.","ps":"have/has + تېر مفعول تېر مهال له اوس سره نښلوي — د تجربو او پایلو لپاره چې اوس مهم دي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I have visited Paris.","ps":"زه پاریس ته تللی یم."},{"en":"She has finished her homework.","ps":"هغې خپل کورنی کار بشپړ کړی."},{"en":"We have lived here for five years.","ps":"موږ دلته پنځه کاله ژوند کوو."},{"en":"He has never eaten sushi.","ps":"هغه هیڅکله سوشي نه دي خوړلي."},{"en":"They have already left.","ps":"دوی مخکې تللي دي."},{"en":"Have you seen this movie?","ps":"آیا دا فلم دې لیدلی دی؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I have visit Paris. | Right: I have visited Paris. | Present perfect needs the past participle form, not the base verb.","ps":"اوسنی بشپړ مهال تېر مفعول بڼه غواړي، نه اصلي فعل."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-ever-never-already-yet","titleEn":"ever / never / just / already / yet","titlePs":"د تجربې او وخت کلمې: ever, never, just, already, yet","levelNumber":null,"acceptedLevelId":"elementary","branchId":"tenses","subbranchId":"ever-never-just-already-yet","masteryConceptId":"grammar-concept-ever-never-just-already-yet","prerequisites":["grammar-d20-elementary-present-perfect-intro"],"wizardSessionId":"grammar-d20-elementary-ever-never-already-yet-wiz","testSessionId":"grammar-d20-elementary-ever-never-already-yet-test","blocks":[{"type":"explanation","titleEn":"ever / never / just / already / yet","en":"ever/never ask/state about experience. just = very recently. already = sooner than expected. yet = in negatives/questions, meaning \"up to now\".","ps":"ever/never د تجربې په اړه پوښتنه/بیان کوي. just = تازه اوسمهاله. already = د تمې نه مخکې. yet = په نفي/پوښتنه کې، د \"تر اوسه\" معنی لري."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Have you ever been to London?","ps":"آیا دې کله لندن ته تلي یې؟"},{"en":"I have never seen snow.","ps":"ما هیڅکله واوره نه ده لیدلې."},{"en":"She has just arrived.","ps":"هغه اوس مهال راورسیده."},{"en":"We have already eaten.","ps":"موږ مخکې خواړه خوړلي دي."},{"en":"I haven't finished yet.","ps":"زه تر اوسه پای ته نه یم رسولی."},{"en":"Has he called yet?","ps":"آیا هغه تر اوسه زنګ وهلی؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I have finished already yet. | Right: I have already finished. / I haven't finished yet. | already is for positive sentences; yet is for negatives and questions — never combine them.","ps":"already د مثبتو جملو لپاره دی؛ yet د نفي/پوښتنو لپاره دی، دواړه یوځای مه کاروئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-present-perfect-vs-past-simple","titleEn":"Present Perfect vs Finished Past (Introduction)","titlePs":"اوسنی بشپړ مهال بمقابل پای ته رسیدلی تېر (پېژندنه)","levelNumber":null,"acceptedLevelId":"elementary","branchId":"tenses","subbranchId":"present-perfect-vs-finished-past","masteryConceptId":"grammar-concept-present-perfect-vs-finished-past","prerequisites":["grammar-d20-elementary-ever-never-already-yet"],"wizardSessionId":"grammar-d20-elementary-present-perfect-vs-past-simple-wiz","testSessionId":"grammar-d20-elementary-present-perfect-vs-past-simple-test","blocks":[{"type":"explanation","titleEn":"Present Perfect vs Finished Past (Introduction)","en":"Present perfect: no specific time given, connects to now. Past simple: specific finished time (yesterday, last year).","ps":"اوسنی بشپړ مهال: ځانګړی وخت نه ښودل کیږي، له اوسه سره نښلي. تېر ساده مهال: ځانګړی پای ته رسیدلی وخت (پرون، تیر کال)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I have seen that film. (no time given)","ps":"ما هغه فلم لیدلی دی. (وخت نه دی ښودل شوی)"},{"en":"I saw that film last week. (specific time)","ps":"ما هغه فلم تیره اونۍ ولید. (ځانګړی وخت)"},{"en":"She has visited Kabul.","ps":"هغه کابل ته تللې ده."},{"en":"She visited Kabul in 2019.","ps":"هغه په ۲۰۱۹ کال کې کابل ته لاړه."},{"en":"Have you finished your work?","ps":"آیا خپل کار دې بشپړ کړی؟"},{"en":"Did you finish your work yesterday?","ps":"آیا پرون خپل کار بشپړ کړ؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I have seen that film yesterday. | Right: I saw that film yesterday. | A specific past time word like yesterday requires past simple, not present perfect.","ps":"د پرون په څېر ځانګړی تېر وخت تېر ساده مهال غواړي، نه اوسنی بشپړ مهال."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-modals-ability-permission-advice","titleEn":"Modals: Ability, Permission, Advice, Obligation","titlePs":"مودل افعال: توان، اجازه، سلا، دنده","levelNumber":null,"acceptedLevelId":"elementary","branchId":"modals","subbranchId":"modals-ability-permission-advice-obligation","masteryConceptId":"grammar-concept-modals-ability-permission-advice-obligation","prerequisites":[],"wizardSessionId":"grammar-d20-elementary-modals-ability-permission-advice-wiz","testSessionId":"grammar-d20-elementary-modals-ability-permission-advice-test","blocks":[{"type":"explanation","titleEn":"Modals: Ability, Permission, Advice, Obligation","en":"can/could = ability. may/can = permission. should = advice. must/have to = obligation.","ps":"can/could = توان. may/can = اجازه. should = سلا. must/have to = دنده."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I can speak two languages. (ability)","ps":"زه دوه ژبې خبرې کولی شم. (توان)"},{"en":"May I leave early? (permission)","ps":"آیا زه کولی شم ژر لاړ شم؟ (اجازه)"},{"en":"You should study every day. (advice)","ps":"ته باید هره ورځ ولولې. (سلا)"},{"en":"We must arrive on time. (obligation)","ps":"موږ باید په وخت راورسو. (دنده)"},{"en":"She could swim when she was five. (past ability)","ps":"هغه کله چې پنځه کلنه وه لامبل یې کولی شوای. (تېر توان)"},{"en":"You have to bring your ID card. (obligation)","ps":"ته باید خپل پیژندپاڼه راوړې. (دنده)"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: You should to study. | Right: You should study. | Never use to after should — it takes the base verb directly.","ps":"د should وروسته هیڅکله to نه راځي، مستقیم اصلي فعل اخلي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-first-conditional","titleEn":"First Conditional","titlePs":"لومړی شرطي جوړښت","levelNumber":null,"acceptedLevelId":"elementary","branchId":"conditionals","subbranchId":"first-conditional","masteryConceptId":"grammar-concept-first-conditional","prerequisites":["grammar-d20-elementary-modals-ability-permission-advice"],"wizardSessionId":"grammar-d20-elementary-first-conditional-wiz","testSessionId":"grammar-d20-elementary-first-conditional-test","blocks":[{"type":"explanation","titleEn":"First Conditional","en":"If + present simple, will + base verb — for real, possible future situations.","ps":"If + اوسنی ساده مهال، will + اصلي فعل — د واقعي، ممکنه راتلونکو حالاتو لپاره."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"If it rains, I will stay home.","ps":"که باران وشي، زه به کور کې پاتې شم."},{"en":"If you study hard, you will pass.","ps":"که سخت ولولې، به بریالی شې."},{"en":"If she calls, tell her I am busy.","ps":"که هغه زنګ ووهي، ووایه چې زه بوخت یم."},{"en":"We will be late if the bus does not come.","ps":"که بس رانشي موږ به ناوخته شو."},{"en":"If he doesn't hurry, he will miss the train.","ps":"که هغه بیړه ونه کړي، ریل به له لاسه ورکړي."},{"en":"If you don't eat, you will be hungry.","ps":"که ونه خورې، به وږی شې."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: If it will rain, I will stay home. | Right: If it rains, I will stay home. | The if-clause uses present simple, not will, even though it refers to the future.","ps":"د if برخه اوسنی ساده مهال کاروي، نه will، که څه هم راتلونکي ته اشاره کوي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-gerund-infinitive-basics","titleEn":"Gerund and Infinitive Basics","titlePs":"د Gerund او Infinitive بنسټونه","levelNumber":null,"acceptedLevelId":"elementary","branchId":"verb-patterns","subbranchId":"gerund-infinitive-basics","masteryConceptId":"grammar-concept-gerund-infinitive-basics","prerequisites":[],"wizardSessionId":"grammar-d20-elementary-gerund-infinitive-basics-wiz","testSessionId":"grammar-d20-elementary-gerund-infinitive-basics-test","blocks":[{"type":"explanation","titleEn":"Gerund and Infinitive Basics","en":"Some verbs are followed by -ing (enjoy, finish). Some are followed by to + base verb (want, decide).","ps":"ځینې افعال -ing تعقیبوي (enjoy, finish). ځینې نور to + اصلي فعل تعقیبوي (want, decide)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I enjoy reading books.","ps":"زه د کتابونو لوستل خوښوم."},{"en":"She finished doing her homework.","ps":"هغې خپل کورنی کار بشپړ کړ."},{"en":"We want to travel next year.","ps":"موږ غواړو بله کال سفر وکړو."},{"en":"He decided to leave early.","ps":"هغه پرېکړه وکړه چې ژر لاړ شي."},{"en":"They like playing football.","ps":"دوی د فوټبال لوبول خوښوي."},{"en":"I hope to see you soon.","ps":"زه هیله لرم چې ژر به دې وګورم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I enjoy to read books. | Right: I enjoy reading books. | enjoy is always followed by -ing, never to + base verb.","ps":"enjoy تل -ing تعقیبوي، هیڅکله to + اصلي فعل نه."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-defining-relative-clauses","titleEn":"Defining Relative Clauses (who/which/that)","titlePs":"تعریفي وابسته جملې (who/which/that)","levelNumber":null,"acceptedLevelId":"elementary","branchId":"relative-clauses","subbranchId":"defining-relative-clauses","masteryConceptId":"grammar-concept-defining-relative-clauses","prerequisites":[],"wizardSessionId":"grammar-d20-elementary-defining-relative-clauses-wiz","testSessionId":"grammar-d20-elementary-defining-relative-clauses-test","blocks":[{"type":"explanation","titleEn":"Defining Relative Clauses (who/which/that)","en":"who = people. which = things. that = people or things. These clauses give essential information about the noun.","ps":"who = خلک. which = شیان. that = خلک یا شیان. دا جملې د نوم په اړه اړین معلومات ورکوي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The teacher who helped me is kind.","ps":"هغه ښوونکی چې زما سره یې مرسته وکړه مهربان دی."},{"en":"I lost the book that you gave me.","ps":"ما هغه کتاب ورک کړ چې تا راکړی و."},{"en":"This is the car which I bought.","ps":"دا هغه موټر دی چې ما یې واخیست."},{"en":"The woman who lives next door is a doctor.","ps":"هغه ښځه چې تر څنګ ژوند کوي ډاکټره ده."},{"en":"I need a pen that writes well.","ps":"زه یو داسې قلم ته اړتیا لرم چې ښه لیکي."},{"en":"The students who study hard succeed.","ps":"هغه زده کوونکي چې سخت لولي بریالي کیږي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The teacher which helped me is kind. | Right: The teacher who helped me is kind. | Use who for people, not which.","ps":"د خلکو لپاره who کارول کیږي، نه which."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-sentence-combining","titleEn":"Combining Sentences with Connectors","titlePs":"د نښلونکو له لارې د جملو یوځای کول","levelNumber":null,"acceptedLevelId":"elementary","branchId":"connectors","subbranchId":"sentence-combining-elementary","masteryConceptId":"grammar-concept-sentence-combining-elementary","prerequisites":["grammar-d20-beginner-conjunctions"],"wizardSessionId":"grammar-d20-elementary-sentence-combining-wiz","testSessionId":"grammar-d20-elementary-sentence-combining-test","blocks":[{"type":"explanation","titleEn":"Combining Sentences with Connectors","en":"Use connectors like although, however, when, while, before, after to combine two related ideas into one sentence.","ps":"د although, however, when, while, before, after په څېر نښلونکي وکاروئ ترڅو دوه اړونده نظرونه یوه جمله کې یوځای کړئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Although it was raining, we went outside.","ps":"که څه هم باران وشو، موږ بهر لاړو."},{"en":"We finished the work before lunch.","ps":"موږ کار له غرمې ډوډۍ مخکې بشپړ کړ."},{"en":"After she arrived, the meeting started.","ps":"وروسته له دې چې هغه راورسیده، غونډه پیل شوه."},{"en":"While I was cooking, he cleaned the house.","ps":"پداسې حال کې چې زه پخول کولم، هغه کور پاک کړ."},{"en":"She passed the exam; however, she was not happy.","ps":"هغه ازموینه تیره کړه؛ خو، هغه خوشحاله نه وه."},{"en":"When the bell rings, class begins.","ps":"کله چې زنګ وږغیږي ټولګی پیل کیږي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Although it was raining, but we went outside. | Right: Although it was raining, we went outside. | Do not use although and but together — choose one connector.","ps":"although او but یوځای مه کاروئ، یوازې یو نښلونکی وکاروئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-passive-voice-intro","titleEn":"Passive Voice: Introduction","titlePs":"مجهول جوړښت: پېژندنه","levelNumber":null,"acceptedLevelId":"elementary","branchId":"voice","subbranchId":"passive-voice-introduction","masteryConceptId":"grammar-concept-passive-voice-introduction","prerequisites":["grammar-d20-elementary-present-perfect-vs-past-simple"],"wizardSessionId":"grammar-d20-elementary-passive-voice-intro-wiz","testSessionId":"grammar-d20-elementary-passive-voice-intro-test","blocks":[{"type":"explanation","titleEn":"Passive Voice: Introduction","en":"am/is/are/was/were + past participle. Use passive when the action matters more than who did it.","ps":"am/is/are/was/were + تېر مفعول. مجهول کاروو کله چې کړنه له کوونکي زیاته مهمه وي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The letter was written by Ahmad.","ps":"لیک د احمد لخوا ولیکل شو."},{"en":"The car is repaired every year.","ps":"موټر هر کال ترمیم کیږي."},{"en":"English is spoken in many countries.","ps":"انګلیسي په ډېرو هیوادونو کې خبرې کیږي."},{"en":"The house was built in 1990.","ps":"کور په ۱۹۹۰ کال کې جوړ شو."},{"en":"The exam is graded by the teacher.","ps":"ازموینه د ښوونکي لخوا نمره کیږي."},{"en":"This bread is made every morning.","ps":"دا ډوډۍ هره سهار جوړیږي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The letter written by Ahmad. | Right: The letter was written by Ahmad. | The passive always needs a form of be before the past participle.","ps":"مجهول تل د تېر مفعول مخکې د be بڼه غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-future-forms-comparison","titleEn":"Future Forms Comparison (will vs going to)","titlePs":"د راتلونکي بڼو پرتله (will بمقابل going to)","levelNumber":null,"acceptedLevelId":"elementary","branchId":"tenses","subbranchId":"future-forms-comparison","masteryConceptId":"grammar-concept-future-forms-comparison","prerequisites":["grammar-d20-beginner-future-going-to"],"wizardSessionId":"grammar-d20-elementary-future-forms-comparison-wiz","testSessionId":"grammar-d20-elementary-future-forms-comparison-test","blocks":[{"type":"explanation","titleEn":"Future Forms Comparison (will vs going to)","en":"Use going to for plans decided before speaking. Use will for decisions made at the moment of speaking, and predictions.","ps":"د خبرو کولو مخکې پرېکړل شویو پلانونو لپاره going to کاروو. د خبرو کولو په شیبه کې پرېکړو، او وړاندوینو لپاره will کاروو."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I am going to visit my aunt this weekend. (already planned)","ps":"زه به دې اونۍ پای ته خپلې خالې کره لاړ شم. (مخکې پلان شوی)"},{"en":"The phone is ringing — I will answer it. (decided now)","ps":"ټیلیفون ږغیږي — زه به ځواب ورکړم. (اوس مهال پرېکړه)"},{"en":"I think it will rain tomorrow. (prediction)","ps":"زه فکر کوم چې سبا به باران وشي. (وړاندوینه)"},{"en":"We are going to open a new shop next year.","ps":"موږ به بله کال نوی دوکان پرانیزو."},{"en":"Don't worry, I will help you.","ps":"مه پرېشانه، زه به له تا سره مرسته وکړم."},{"en":"She is going to study medicine.","ps":"هغه به طب ولولي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I will visit my aunt this weekend. (already planned) | Right: I am going to visit my aunt this weekend. | A plan already decided uses going to, not will.","ps":"مخکې پرېکړل شوی پلان going to کاروي، نه will."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-quantifiers","titleEn":"Quantifiers: a few, a little, a lot of, plenty of","titlePs":"د اندازې کلمات: a few, a little, a lot of, plenty of","levelNumber":null,"acceptedLevelId":"elementary","branchId":"quantifiers","subbranchId":"quantifiers-elementary","masteryConceptId":"grammar-concept-quantifiers-elementary","prerequisites":["grammar-d20-basic-countable-intro"],"wizardSessionId":"grammar-d20-elementary-quantifiers-wiz","testSessionId":"grammar-d20-elementary-quantifiers-test","blocks":[{"type":"explanation","titleEn":"Quantifiers: a few, a little, a lot of, plenty of","en":"a few/many = countable nouns. a little/much = uncountable nouns. a lot of/plenty of = both.","ps":"a few/many = د شمېرلو وړ نومونه. a little/much = د شمېرلو نه وړ نومونه. a lot of/plenty of = دواړه."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I have a few friends here.","ps":"زه دلته یو څو ملګري لرم."},{"en":"There is a little water left.","ps":"لږې اوبه پاتې دي."},{"en":"She has a lot of books.","ps":"هغه ډېر کتابونه لري."},{"en":"We have plenty of time.","ps":"موږ کافي وخت لرو."},{"en":"He doesn't have many friends.","ps":"هغه ډېر ملګري نه لري."},{"en":"There isn't much rice left.","ps":"ډېرې وریجې پاتې نه دي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: a few water | Right: a little water | water is uncountable, so use a little, not a few.","ps":"اوبه د شمېرلو وړ نه دي، نو a little کارول کیږي، نه a few."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-elementary-error-correction-mixed-tenses","titleEn":"Error Correction Across Mixed Tenses","titlePs":"د ګډو مهالونو تېروتنو سمون","levelNumber":null,"acceptedLevelId":"elementary","branchId":"review","subbranchId":"error-correction-mixed-tenses","masteryConceptId":"grammar-concept-error-correction-mixed-tenses","prerequisites":["grammar-d20-elementary-passive-voice-intro","grammar-d20-elementary-future-forms-comparison"],"wizardSessionId":"grammar-d20-elementary-error-correction-mixed-tenses-wiz","testSessionId":"grammar-d20-elementary-error-correction-mixed-tenses-test","blocks":[{"type":"explanation","titleEn":"Error Correction Across Mixed Tenses","en":"Review checkpoint: identify and correct errors mixing present, past, continuous, and perfect tenses in one passage.","ps":"د بیاکتنې پړاو: د اوسنی، تېر، دوامداره، او بشپړ مهالونو ګډو تېروتنو پیژندل او سمون."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Wrong: I go to school yesterday. Right: I went to school yesterday.","ps":"غلط: زه پرون ښوونځي ته ځم. سم: زه پرون ښوونځي ته لاړم."},{"en":"Wrong: She have finished. Right: She has finished.","ps":"غلط: هغې بشپړ کړي. سم: هغې بشپړ کړي دي."},{"en":"Wrong: I am study now. Right: I am studying now.","ps":"غلط: زه اوس مطالعه یم. سم: زه اوس مطالعه کوم."},{"en":"Wrong: We was happy. Right: We were happy.","ps":"غلط: موږ خوشحاله وو. سم: موږ خوشحاله وو."},{"en":"Wrong: He don't like tea. Right: He doesn't like tea.","ps":"غلط: هغه چای نه خوښوي. سم: هغه چای نه خوښوي."},{"en":"Wrong: Did you went there? Right: Did you go there?","ps":"غلط: آیا هلته لاړې؟ سم: آیا هلته لاړې؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: (see examples — mixed tense review) | Right: (see examples — mixed tense review) | This checkpoint tests recognition of tense errors across all Elementary-level forms.","ps":"دا پړاو د ابتدايي کچې ټولو بڼو د مهال تېروتنو پیژندنه ازموي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-perfect-vs-past-simple","titleEn":"Present Perfect vs Past Simple (Deeper)","titlePs":"اوسنی بشپړ مهال بمقابل تېر ساده مهال (ژور کتنه)","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"tenses","subbranchId":"present-perfect-vs-past-simple","masteryConceptId":"grammar-concept-present-perfect-vs-past-simple","prerequisites":[],"wizardSessionId":"grammar-d20-intermediate-perfect-vs-past-simple-wiz","testSessionId":"grammar-d20-intermediate-perfect-vs-past-simple-test","blocks":[{"type":"explanation","titleEn":"Present Perfect vs Past Simple (Deeper)","en":"Deeper contrast: present perfect for unfinished time periods (this week, so far); past simple for finished time periods (last week).","ps":"ژوره پرتله: اوسنی بشپړ مهال د نه پای ته رسیدلو وخت دورو لپاره (دې اونۍ کې، تراوسه)؛ تېر ساده مهال د پای ته رسیدلو وخت دورو لپاره (تیره اونۍ)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I have read three books this month.","ps":"ما دې میاشتې کې درې کتابونه لوستي دي."},{"en":"I read three books last month.","ps":"ما تیره میاشت درې کتابونه ولوستل."},{"en":"She has worked here since 2020.","ps":"هغه له ۲۰۲۰ کال راهیسې دلته کار کوي."},{"en":"She worked there for two years, then left.","ps":"هغه هلته دوه کاله کار وکړ، بیا یې پرېښود."},{"en":"Have you ever visited Japan?","ps":"آیا کله جاپان ته تللی یې؟"},{"en":"Did you visit Japan when you were young?","ps":"کله چې ځوان وې جاپان ته تللی وې؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I have visited Japan last year. | Right: I visited Japan last year. | A specific finished-time phrase always forces past simple, even with have.","ps":"ځانګړی پای ته رسیدلی وخت تل تېر ساده مهال غواړي، حتی که have شتون ولري."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-present-perfect-continuous","titleEn":"Present Perfect Continuous","titlePs":"اوسنی بشپړ دوامداره مهال","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"tenses","subbranchId":"present-perfect-continuous","masteryConceptId":"grammar-concept-present-perfect-continuous","prerequisites":["grammar-d20-intermediate-perfect-vs-past-simple"],"wizardSessionId":"grammar-d20-intermediate-present-perfect-continuous-wiz","testSessionId":"grammar-d20-intermediate-present-perfect-continuous-test","blocks":[{"type":"explanation","titleEn":"Present Perfect Continuous","en":"have/has been + verb-ing emphasizes the duration of an action continuing up to now.","ps":"have/has been + verb-ing د هغې کړنې موده ټینګاروي چې تر اوسه دوام لري."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I have been studying for three hours.","ps":"زه درې ساعته کیږي چې ولولم."},{"en":"She has been working here since June.","ps":"هغه د جون میاشتې راهیسې دلته کار کوي."},{"en":"We have been waiting for the bus.","ps":"موږ د بس انتظار باسو."},{"en":"It has been raining all day.","ps":"ټوله ورځ باران دی."},{"en":"They have been living in Kabul for ten years.","ps":"دوی لس کاله کیږي چې کابل کې ژوند کوي."},{"en":"How long have you been learning English?","ps":"له کومه وخته راهیسې انګلیسي زده کوې؟"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I have been study for three hours. | Right: I have been studying for three hours. | been must be followed by the -ing form.","ps":"د been وروسته -ing بڼه راځي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-passive-across-tenses","titleEn":"Passive Voice Across Common Tenses","titlePs":"مجهول جوړښت په عادي مهالونو کې","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"voice","subbranchId":"passive-across-common-tenses","masteryConceptId":"grammar-concept-passive-across-common-tenses","prerequisites":["grammar-d20-intermediate-present-perfect-continuous"],"wizardSessionId":"grammar-d20-intermediate-passive-across-tenses-wiz","testSessionId":"grammar-d20-intermediate-passive-across-tenses-test","blocks":[{"type":"explanation","titleEn":"Passive Voice Across Common Tenses","en":"The passive can be formed in present simple, past simple, present perfect, and future: be + past participle, with the tense carried by be.","ps":"مجهول جوړښت د اوسني ساده، تېر ساده، اوسني بشپړ، او راتلونکي مهالونو کې جوړیدی شي: be + تېر مفعول، مهال د be له لارې ښودل کیږي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The report is checked every week. (present)","ps":"راپور هره اونۍ کتل کیږي. (اوسنی)"},{"en":"The report was checked yesterday. (past)","ps":"راپور پرون وکتل شو. (تېر)"},{"en":"The report has been checked already. (present perfect)","ps":"راپور مخکې کتل شوی دی. (اوسنی بشپړ)"},{"en":"The report will be checked tomorrow. (future)","ps":"راپور به سبا وکتل شي. (راتلونکی)"},{"en":"New employees are trained by the manager.","ps":"نوي کارکوونکي د مدیر لخوا روزل کیږي."},{"en":"The bridge is being built now.","ps":"پل اوس جوړیږي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The report has checked already. | Right: The report has been checked already. | Present perfect passive needs has/have BEEN + past participle.","ps":"اوسنی بشپړ مجهول د has/have BEEN + تېر مفعول غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-reported-statements","titleEn":"Reported Statements","titlePs":"رپوټ شوي جملات","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"reported-speech","subbranchId":"reported-statements","masteryConceptId":"grammar-concept-reported-statements","prerequisites":["grammar-d20-intermediate-passive-across-tenses"],"wizardSessionId":"grammar-d20-intermediate-reported-statements-wiz","testSessionId":"grammar-d20-intermediate-reported-statements-test","blocks":[{"type":"explanation","titleEn":"Reported Statements","en":"When reporting statements, tenses usually shift back one step: present→past, past→past perfect.","ps":"د رپوټ کولو پر مهال، مهالونه معمولا یو ګام شاته ورکشیږي: اوسنی→تېر، تېر→تېر بشپړ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"\"I am tired.\" → She said she was tired.","ps":"\"زه ستړی یم.\" → هغې وویل چې ستړې ده."},{"en":"\"I work in Kabul.\" → He said he worked in Kabul.","ps":"\"زه کابل کې کار کوم.\" → هغه ویل چې کابل کې کار کاوه."},{"en":"\"I will call you.\" → She said she would call me.","ps":"\"زه به تاته زنګ ووهم.\" → هغې وویل چې به ما ته زنګ ووهي."},{"en":"\"I have finished.\" → He said he had finished.","ps":"\"ما بشپړ کړی دی.\" → هغه وویل چې بشپړ یې کړی و."},{"en":"\"I can help.\" → She said she could help.","ps":"\"زه کولی شم مرسته وکړم.\" → هغې وویل چې کولی شي مرسته وکړي."},{"en":"\"I saw him yesterday.\" → He said he had seen him the day before.","ps":"\"ما پرون هغه ولید.\" → هغه وویل چې مخکینۍ ورځ یې هغه لیدلی و."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: She said she is tired. | Right: She said she was tired. | The reporting verb said usually requires the tense to shift back.","ps":"د رپوټ کولو فعل said معمولا مهال شاته اړوي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-reported-questions-commands","titleEn":"Reported Questions and Commands","titlePs":"رپوټ شوي پوښتنې او امرونه","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"reported-speech","subbranchId":"reported-questions-and-commands","masteryConceptId":"grammar-concept-reported-questions-and-commands","prerequisites":["grammar-d20-intermediate-reported-statements"],"wizardSessionId":"grammar-d20-intermediate-reported-questions-commands-wiz","testSessionId":"grammar-d20-intermediate-reported-questions-commands-test","blocks":[{"type":"explanation","titleEn":"Reported Questions and Commands","en":"Reported yes/no questions use if/whether. Reported WH questions keep the question word. Word order becomes normal statement order. Commands use asked/told + to + base verb.","ps":"رپوټ شوي هو/نه پوښتنې if/whether کاروي. رپوټ شوي WH پوښتنې پوښتنیز کلمه ساتي. کلمو ترتیب عادي جملې ترتیب کیږي. امرونه asked/told + to + اصلي فعل کاروي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"\"Are you ready?\" → She asked if I was ready.","ps":"\"چمتو یې؟\" → هغې وپوښتل چې زه چمتو یم که نه."},{"en":"\"Where do you live?\" → He asked where I lived.","ps":"\"چیرته ژوند کوې؟\" → هغه وپوښتل چې زه چیرته ژوند کوم."},{"en":"\"Close the door.\" → She told me to close the door.","ps":"\"دروازه وتړه.\" → هغې راته وویل چې دروازه وتړم."},{"en":"\"Don't be late.\" → He told us not to be late.","ps":"\"ناوخته مه کوه.\" → هغه راته وویل چې ناوخته دې نه شي."},{"en":"\"What time is it?\" → She asked what time it was.","ps":"\"څو بجې دي؟\" → هغې وپوښتل چې څو بجې دي."},{"en":"\"Please help me.\" → He asked me to help him.","ps":"\"مهرباني وکړه مرسته وکړه.\" → هغه وغوښتل چې مرسته وکړم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: She asked did I ready. | Right: She asked if I was ready. | Reported questions use if/whether and normal statement word order, not question word order.","ps":"رپوټ شوې پوښتنې if/whether او عادي جملې ترتیب کاروي، نه د پوښتنې ترتیب."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-second-conditional","titleEn":"Second Conditional","titlePs":"دویم شرطي جوړښت","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"conditionals","subbranchId":"second-conditional","masteryConceptId":"grammar-concept-second-conditional","prerequisites":["grammar-d20-intermediate-reported-questions-commands"],"wizardSessionId":"grammar-d20-intermediate-second-conditional-wiz","testSessionId":"grammar-d20-intermediate-second-conditional-test","blocks":[{"type":"explanation","titleEn":"Second Conditional","en":"If + past simple, would + base verb — for unreal or unlikely present/future situations.","ps":"If + تېر ساده مهال، would + اصلي فعل — د غیر واقعي یا لږ ممکنه اوسني/راتلونکي حالاتو لپاره."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"If I had more money, I would travel.","ps":"که زما سره ډېرې پیسې وای، سفر به مې کاوه."},{"en":"If she studied harder, she would pass.","ps":"که هغه ډېر ولوستلای، بریالۍ به شوای."},{"en":"What would you do if you won the lottery?","ps":"که د لاټري وګټلای، به دې څه کول؟"},{"en":"If I were you, I would apologize.","ps":"که زه ستا ځای وای، بخښنه به مې غوښتله."},{"en":"We would help if we could.","ps":"موږ به مرسته کوله که وکولی شوای."},{"en":"If he had a car, he would drive to work.","ps":"که هغه موټر لرلای، کار ته به یې موټر چلاوه."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: If I have more money, I would travel. | Right: If I had more money, I would travel. | The if-clause uses past simple, not present, for unreal situations.","ps":"د غیر واقعي حالاتو لپاره if برخه تېر ساده مهال کاروي، نه اوسنی."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-modal-deduction-present","titleEn":"Modal Deduction: Present","titlePs":"د مودل استنباط: اوسنی","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"modals","subbranchId":"modal-deduction-present","masteryConceptId":"grammar-concept-modal-deduction-present","prerequisites":[],"wizardSessionId":"grammar-d20-intermediate-modal-deduction-present-wiz","testSessionId":"grammar-d20-intermediate-modal-deduction-present-test","blocks":[{"type":"explanation","titleEn":"Modal Deduction: Present","en":"must = certain. might/may/could = possible. can't = certain not — used to guess about present situations.","ps":"must = ډاډمن. might/may/could = ممکن. can't = ډاډمن نه — د اوسنیو حالاتو په اړه اټکل کولو لپاره کارول کیږي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"She isn't answering — she must be busy.","ps":"هغه ځواب نه ورکوي — باید بوخته وي."},{"en":"He might be at home now.","ps":"هغه ممکن اوس کور کې وي."},{"en":"That can't be true.","ps":"دا نشي رښتیا کیدلی."},{"en":"They could be waiting outside.","ps":"دوی ممکن بهر انتظار کوي."},{"en":"She must know the answer — she studied all night.","ps":"هغه باید ځواب پیژني — ټوله شپه یې ولوستل."},{"en":"It may be too late to call him.","ps":"ممکن دومره ناوخته وي چې هغه ته زنګ ووهو."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: She must to be busy. | Right: She must be busy. | must is followed directly by the base verb, never to.","ps":"د must وروسته مستقیم اصلي فعل راځي، هیڅکله to نه."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-modal-deduction-past","titleEn":"Modal Deduction: Past","titlePs":"د مودل استنباط: تېر","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"modals","subbranchId":"modal-deduction-past","masteryConceptId":"grammar-concept-modal-deduction-past","prerequisites":["grammar-d20-intermediate-modal-deduction-present"],"wizardSessionId":"grammar-d20-intermediate-modal-deduction-past-wiz","testSessionId":"grammar-d20-intermediate-modal-deduction-past-test","blocks":[{"type":"explanation","titleEn":"Modal Deduction: Past","en":"must have + past participle = certain about the past. might/could have = possible. can't have = certain not.","ps":"must have + تېر مفعول = د تېر په اړه ډاډمن. might/could have = ممکن. can't have = ډاډمن نه."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"He must have forgotten the meeting.","ps":"هغه باید غونډه هیره کړې وي."},{"en":"She might have missed the bus.","ps":"هغه ممکن بس له لاسه ورکړی وي."},{"en":"They can't have arrived yet — it's too early.","ps":"دوی نشي رسیدلی — ډېر ژر دی."},{"en":"I could have made a mistake.","ps":"زه ممکن غلطي کړې وي."},{"en":"She must have studied hard to pass that exam.","ps":"هغه باید سخت لوستلي وي چې هغه ازموینه یې تیره کړه."},{"en":"He might have left already.","ps":"هغه ممکن مخکې تللی وي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: He must forgot the meeting. | Right: He must have forgotten the meeting. | Past deduction needs must/might/could + HAVE + past participle.","ps":"د تېر استنباط must/might/could + HAVE + تېر مفعول غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-relative-clauses-defining-nondefining","titleEn":"Defining and Non-Defining Relative Clauses","titlePs":"تعریفي او غیر تعریفي وابسته جملې","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"relative-clauses","subbranchId":"defining-and-non-defining-relative-clauses","masteryConceptId":"grammar-concept-defining-and-non-defining-relative-clauses","prerequisites":["grammar-d20-elementary-defining-relative-clauses"],"wizardSessionId":"grammar-d20-intermediate-relative-clauses-defining-nondefining-wiz","testSessionId":"grammar-d20-intermediate-relative-clauses-defining-nondefining-test","blocks":[{"type":"explanation","titleEn":"Defining and Non-Defining Relative Clauses","en":"Defining clauses give essential information (no commas). Non-defining clauses give extra information (use commas).","ps":"تعریفي جملې اړین معلومات ورکوي (کوما نه لري). غیر تعریفي جملې اضافي معلومات ورکوي (کوما کاروي)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The man who called is my uncle. (defining)","ps":"هغه سړی چې زنګ یې وواهه زما تره دی. (تعریفي)"},{"en":"My uncle, who lives in Herat, called me. (non-defining)","ps":"زما تره، چې هرات کې ژوند کوي، ما ته یې زنګ ووهه. (غیر تعریفي)"},{"en":"The book that I borrowed was interesting. (defining)","ps":"هغه کتاب چې ما پور کړی و په زړه پورې و. (تعریفي)"},{"en":"This novel, which won an award, is very popular. (non-defining)","ps":"دا ناول، چې جایزه یې ګټلې، ډېر مشهور دی. (غیر تعریفي)"},{"en":"Students who arrive late must wait outside. (defining)","ps":"هغه زده کوونکي چې ناوخته راځي باید بهر انتظار وکړي. (تعریفي)"},{"en":"Kabul, which is the capital, has many universities. (non-defining)","ps":"کابل، چې پلازمینه ده، ډېرې پوهنتونونه لري. (غیر تعریفي)"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: My uncle who lives in Herat called me. (implies I have several uncles) | Right: My uncle, who lives in Herat, called me. | Without commas, the clause sounds essential/defining, which can create the wrong meaning for a unique person.","ps":"پرته له کوما، جمله تعریفي ښکاري چې کیدای شي غلط مانا ورکړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-gerund-infinitive-patterns","titleEn":"Gerund/Infinitive Patterns (Deeper)","titlePs":"د Gerund/Infinitive بڼې (ژور کتنه)","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"verb-patterns","subbranchId":"gerund-infinitive-patterns","masteryConceptId":"grammar-concept-gerund-infinitive-patterns","prerequisites":["grammar-d20-elementary-gerund-infinitive-basics"],"wizardSessionId":"grammar-d20-intermediate-gerund-infinitive-patterns-wiz","testSessionId":"grammar-d20-intermediate-gerund-infinitive-patterns-test","blocks":[{"type":"explanation","titleEn":"Gerund/Infinitive Patterns (Deeper)","en":"Some verbs change meaning with gerund vs infinitive (remember, stop, try). Others take both with similar meaning (like, start).","ps":"ځینې افعال د gerund او infinitive سره مانا بدلوي (remember, stop, try). نور دواړه ورته مانا سره اخلي (like, start)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I remember locking the door. (past memory)","ps":"ما په یاد دی چې دروازه مې تړلې وه. (تېره یادونه)"},{"en":"Remember to lock the door. (future reminder)","ps":"دروازه تړل مه هیروه. (راتلونکې یادونه)"},{"en":"She stopped smoking. (quit the habit)","ps":"هغې سیګرټ نوشول پرېښود. (عادت یې پرېښود)"},{"en":"She stopped to smoke. (paused in order to smoke)","ps":"هغه سیګرټ څکولو لپاره ودرېده. (د سیګرټ لپاره ودرېده)"},{"en":"I like swimming. / I like to swim. (both correct)","ps":"زه لامبل خوښوم. (دواړه سم دي)"},{"en":"It started raining. / It started to rain. (both correct)","ps":"باران پیل شو. (دواړه سم دي)"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I remember to lock the door yesterday. | Right: I remember locking the door yesterday. | A past memory uses the gerund, not the infinitive.","ps":"تېره یادونه gerund کاروي، نه infinitive."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-discourse-connectors","titleEn":"Discourse Connectors","titlePs":"د خبرو نښلوونکي","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"connectors","subbranchId":"discourse-connectors","masteryConceptId":"grammar-concept-discourse-connectors","prerequisites":[],"wizardSessionId":"grammar-d20-intermediate-discourse-connectors-wiz","testSessionId":"grammar-d20-intermediate-discourse-connectors-test","blocks":[{"type":"explanation","titleEn":"Discourse Connectors","en":"however, therefore, moreover, in addition, on the other hand, as a result connect ideas across sentences.","ps":"however, therefore, moreover, in addition, on the other hand, as a result جملو ترمنځ نظرونه نښلوي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The plan was good. However, it was expensive.","ps":"پلان ښه و. خو، ګران و."},{"en":"He studied hard. Therefore, he passed easily.","ps":"هغه سخت ولوستل. له همدې امله، اسانه بریالی شو."},{"en":"She is smart. Moreover, she works hard.","ps":"هغه هوښیاره ده. سربېره پردې، سخت کار کوي."},{"en":"The price increased. As a result, sales dropped.","ps":"بیه لوړه شوه. په پایله کې، خرڅلاو راټیټ شو."},{"en":"I like coffee. On the other hand, my sister prefers tea.","ps":"زه قهوه خوښوم. له بلې خوا، خور مې چای غواړي."},{"en":"We need more staff. In addition, we need more equipment.","ps":"موږ نور کارکوونکو ته اړتیا لرو. سربېره پردې، نورو وسایلو ته اړتیا لرو."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The plan was good, however it was expensive. | Right: The plan was good. However, it was expensive. | however typically starts a new sentence with a comma after it, not a comma splice before it.","ps":"however معمولا نوې جمله پیلوي او وروسته یې کوما راځي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-complex-clause-control","titleEn":"Complex Sentence and Clause Control","titlePs":"د پیچلې جملې او فقرو کنترول","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"syntax","subbranchId":"complex-sentence-clause-control","masteryConceptId":"grammar-concept-complex-sentence-clause-control","prerequisites":["grammar-d20-intermediate-discourse-connectors"],"wizardSessionId":"grammar-d20-intermediate-complex-clause-control-wiz","testSessionId":"grammar-d20-intermediate-complex-clause-control-test","blocks":[{"type":"explanation","titleEn":"Complex Sentence and Clause Control","en":"A complex sentence combines an independent clause with one or more dependent clauses using subordinators (because, although, since, if, when).","ps":"پیچلې جمله د یو خپلواک فقرې د یو یا ډېرو تابع فقرو سره یوځای کوي د تابع کوونکو (because, although, since, if, when) په مرسته."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Since it was raining, we cancelled the trip.","ps":"ځکه چې باران و، سفر مو لغوه کړ."},{"en":"Although he was tired, he finished the report.","ps":"که څه هم ستړی و، راپور یې بشپړ کړ."},{"en":"I will call you when I arrive.","ps":"کله چې راورسیدم به تاته زنګ ووهم."},{"en":"Because the exam was difficult, many students failed.","ps":"ځکه چې ازموینه سخته وه، ډېری زده کوونکي پاتې شول."},{"en":"If the weather improves, we will travel tomorrow.","ps":"که هوا ښه شي، به سبا سفر وکړو."},{"en":"She left before the meeting ended.","ps":"هغه له دې مخکې لاړه چې غونډه پای ته ورسیده."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Because the exam was difficult. Many students failed. | Right: Because the exam was difficult, many students failed. | A because-clause alone is not a complete sentence — it must connect to an independent clause.","ps":"یوازې because فقره بشپړه جمله نه ده، باید له خپلواکې فقرې سره ونښلي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-used-to-be-used-to-get-used-to","titleEn":"used to / be used to / get used to","titlePs":"د پخوانیو عادتونو کلمات: used to, be used to, get used to","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"habits","subbranchId":"used-to-be-used-to-get-used-to","masteryConceptId":"grammar-concept-used-to-be-used-to-get-used-to","prerequisites":["grammar-d20-intermediate-complex-clause-control"],"wizardSessionId":"grammar-d20-intermediate-used-to-be-used-to-get-used-to-wiz","testSessionId":"grammar-d20-intermediate-used-to-be-used-to-get-used-to-test","blocks":[{"type":"explanation","titleEn":"used to / be used to / get used to","en":"used to + base verb = past habit, no longer true. be used to + -ing = accustomed to something now. get used to + -ing = becoming accustomed.","ps":"used to + اصلي فعل = تېر عادت، نور رښتیا نه دی. be used to + -ing = اوس د یو شي عادت لرل. get used to + -ing = عادت کیدل."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I used to live in Herat. (past habit, not now)","ps":"زه پخوا هرات کې اوسیدم. (تېر عادت)"},{"en":"She is used to waking up early. (accustomed now)","ps":"هغه د سهار ژر پاڅیدو عادت لري. (اوسنی عادت)"},{"en":"I am getting used to the new schedule. (becoming accustomed)","ps":"زه د نوي مهال ویش عادت کیږم. (عادت کېدل)"},{"en":"We used to play cricket every weekend.","ps":"موږ پخوا هره اونۍ کرکټ لوباوه."},{"en":"He wasn't used to the cold weather at first.","ps":"هغه لومړی د یخنۍ هوا عادت نه درلود."},{"en":"They got used to living without electricity.","ps":"دوی د بریښنا پرته ژوند کولو عادت شول."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I am used to wake up early. | Right: I am used to waking up early. | be used to takes the -ing form, not the base verb.","ps":"be used to -ing بڼه اخلي، نه اصلي فعل."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-wishes-regrets","titleEn":"Wishes and Regrets","titlePs":"هیلې او پښیمانتوبونه","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"unreal-meaning","subbranchId":"wishes-and-regrets","masteryConceptId":"grammar-concept-wishes-and-regrets","prerequisites":["grammar-d20-intermediate-modal-deduction-past"],"wizardSessionId":"grammar-d20-intermediate-wishes-regrets-wiz","testSessionId":"grammar-d20-intermediate-wishes-regrets-test","blocks":[{"type":"explanation","titleEn":"Wishes and Regrets","en":"wish + past simple = present wish. wish + past perfect = regret about the past.","ps":"wish + تېر ساده مهال = اوسنۍ هیله. wish + تېر بشپړ مهال = د تېر پښیمانتوب."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I wish I had more time. (present wish)","ps":"کاش چې زما سره ډېر وخت وای. (اوسنۍ هیله)"},{"en":"I wish I had studied harder. (past regret)","ps":"کاش چې سخت مې لوستلای وای. (تېر پښیمانتوب)"},{"en":"She wishes she lived closer to her family.","ps":"هغه هیله لري چې خپلې کورنۍ ته نږدې اوسیدلای."},{"en":"He wishes he hadn't said that.","ps":"هغه پښیمانه دی چې دا یې وویل."},{"en":"I wish I could speak French.","ps":"کاش چې فرانسوي زده وای."},{"en":"We wish we had brought more water.","ps":"کاش چې نورې اوبه مو راوړي وای."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I wish I have more time. | Right: I wish I had more time. | Present wishes need the PAST tense form of the verb, not present.","ps":"اوسنۍ هیلې د فعل تېره بڼه غواړي، نه اوسنی."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-causative-structures","titleEn":"Causative Structures (have/get something done)","titlePs":"د لامل جوړښتونه","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"causative","subbranchId":"causative-structures","masteryConceptId":"grammar-concept-causative-structures","prerequisites":["grammar-d20-intermediate-wishes-regrets"],"wizardSessionId":"grammar-d20-intermediate-causative-structures-wiz","testSessionId":"grammar-d20-intermediate-causative-structures-test","blocks":[{"type":"explanation","titleEn":"Causative Structures (have/get something done)","en":"have/get + object + past participle = arranging for someone else to do something for you.","ps":"have/get + مفعول + تېر مفعول = د بل چا لخوا د یو کار ترسره کولو تنظیمول."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I had my car repaired.","ps":"ما خپل موټر ترمیم کړاوه."},{"en":"She is getting her hair cut.","ps":"هغه خپل ویښتان قیچي کوي (له بل چا)."},{"en":"We had the house painted last month.","ps":"موږ تیره میاشت کور رنګ کړاوه."},{"en":"He is having his suit made for the wedding.","ps":"هغه د واده لپاره خپل کالي جوړوي (له بل چا)."},{"en":"They got their documents translated.","ps":"دوی خپل اسناد وژباړل (له بل چا)."},{"en":"I need to have this letter typed.","ps":"زه اړتیا لرم چې دا لیک ټایپ شي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I had repaired my car. | Right: I had my car repaired. | The object goes between have and the past participle: have + object + past participle.","ps":"مفعول د have او تېر مفعول ترمنځ راځي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-intermediate-future-continuous-perfect-intro","titleEn":"Future Continuous and Future Perfect (Introduction)","titlePs":"راتلونکی دوامداره او راتلونکی بشپړ (پېژندنه)","levelNumber":null,"acceptedLevelId":"intermediate","branchId":"tenses","subbranchId":"future-continuous-perfect-introduction","masteryConceptId":"grammar-concept-future-continuous-perfect-introduction","prerequisites":["grammar-d20-intermediate-causative-structures"],"wizardSessionId":"grammar-d20-intermediate-future-continuous-perfect-intro-wiz","testSessionId":"grammar-d20-intermediate-future-continuous-perfect-intro-test","blocks":[{"type":"explanation","titleEn":"Future Continuous and Future Perfect (Introduction)","en":"will be + verb-ing = an action in progress at a future time. will have + past participle = an action completed before a future time.","ps":"will be + verb-ing = هغه کړنه چې د راتلونکي یو وخت کې روانه به وي. will have + تېر مفعول = هغه کړنه چې د راتلونکي مخکې پای ته به رسیږي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"This time tomorrow, I will be flying to Kabul.","ps":"سبا په دې وخت، زه به کابل ته الوتم."},{"en":"By next year, she will have graduated.","ps":"تر بلې کال، هغه به فارغ شوې وي."},{"en":"We will be having dinner at 8pm.","ps":"موږ به د ۸ بجو ډوډۍ خورو."},{"en":"By the time you arrive, I will have finished cooking.","ps":"تر هغه چې راورسیږې، زه به پخول بشپړ کړي وي."},{"en":"He will be working when you call.","ps":"کله چې زنګ ووهې هغه به کار کوي."},{"en":"They will have completed the project by Friday.","ps":"دوی به تر جمعې پروژه بشپړه کړې وي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: By next year, she will graduate. | Right: By next year, she will have graduated. | By + future time needs future perfect to show completion before that point, not simple future.","ps":"By + راتلونکی وخت راتلونکی بشپړ مهال غواړي، نه ساده راتلونکی."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-mixed-conditionals","titleEn":"Mixed Conditionals","titlePs":"ګډ شرطي جوړښتونه","levelNumber":null,"acceptedLevelId":"advanced","branchId":"conditionals","subbranchId":"mixed-conditionals","masteryConceptId":"grammar-concept-mixed-conditionals","prerequisites":[],"wizardSessionId":"grammar-d20-advanced-mixed-conditionals-wiz","testSessionId":"grammar-d20-advanced-mixed-conditionals-test","blocks":[{"type":"explanation","titleEn":"Mixed Conditionals","en":"Mixed conditionals combine a past unreal condition with a present result, or a present unreal condition with a past result.","ps":"ګډ شرطي جوړښتونه د تېر غیر واقعي شرط له اوسني پایلې سره، یا د اوسني غیر واقعي شرط له تېرې پایلې سره یوځای کوي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"If I had studied medicine, I would be a doctor now. (past condition, present result)","ps":"که مې طب لوستلی وای، اوس به ډاکټر وای."},{"en":"If she were more organized, she wouldn't have missed the deadline. (present condition, past result)","ps":"که هغه سازمان یافته وای، وخت به یې له لاسه ورنکړی وای."},{"en":"If he weren't so shy, he would have spoken at the conference.","ps":"که هغه دومره شرمیدونکی نه وای، په کنفرانس کې به یې خبرې کولې."},{"en":"If they had planned better, the project wouldn't be behind schedule.","ps":"که یې ښه پلان کړی وای، پروژه به تر مهاله وروسته نه وای."},{"en":"If I weren't so busy, I would have joined you yesterday.","ps":"که زه دومره بوخته نه وای، پرون به له تاسو سره یوځای شوی وای."},{"en":"If she had taken the job, she would be living abroad now.","ps":"که هغه دا دنده منلې وای، اوس به بهر ژوند کاوه."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: If I had studied medicine, I would have been a doctor now. | Right: If I had studied medicine, I would be a doctor now. | When the result is present, use would + base verb, not would have + past participle.","ps":"کله چې پایله اوسنۍ وي، would + اصلي فعل کاروئ، نه would have + تېر مفعول."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-advanced-passive-reporting","titleEn":"Advanced Passive and Reporting Passive","titlePs":"پرمختللی مجهول او د رپوټ مجهول","levelNumber":null,"acceptedLevelId":"advanced","branchId":"voice","subbranchId":"advanced-passive-reporting-passive","masteryConceptId":"grammar-concept-advanced-passive-reporting-passive","prerequisites":["grammar-d20-advanced-mixed-conditionals"],"wizardSessionId":"grammar-d20-advanced-advanced-passive-reporting-wiz","testSessionId":"grammar-d20-advanced-advanced-passive-reporting-test","blocks":[{"type":"explanation","titleEn":"Advanced Passive and Reporting Passive","en":"Reporting passive: It is said/believed/reported that... or Subject + is said/believed + to + infinitive — used for citing general opinion or unconfirmed reports formally.","ps":"د رپوټ مجهول: It is said/believed/reported that... یا فاعل + is said/believed + to + infinitive — د رسمي عمومي نظر یا نامعلومو راپورونو یادولو لپاره کارول کیږي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"It is believed that the policy will change soon.","ps":"داسې باور کیږي چې پالیسي به ژر بدله شي."},{"en":"The company is said to be planning layoffs.","ps":"ویل کیږي چې شرکت د کارکوونکو کمولو پلان لري."},{"en":"It is reported that the negotiations have failed.","ps":"راپور ورکړل شوی چې خبرې اترې ناکامې شوې."},{"en":"He is thought to have left the country.","ps":"فکر کیږي چې هغه هیواد پریښی دی."},{"en":"It is estimated that the project will cost millions.","ps":"اټکل کیږي چې پروژه به میلیونونه لګښت ولري."},{"en":"The building is known to have structural problems.","ps":"پیژندل شوی چې دا ودانۍ جوړښتي ستونزې لري."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: He is said left the country. | Right: He is said to have left the country. | The reporting passive with a subject needs to + infinitive (or to have + past participle for the past).","ps":"د فاعل سره د رپوټ مجهول to + infinitive (یا د تېر لپاره to have + تېر مفعول) غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-inversion","titleEn":"Inversion After Negative or Limiting Expressions","titlePs":"د نفي یا محدودوونکو څرګندونو وروسته وارونتوب","levelNumber":null,"acceptedLevelId":"advanced","branchId":"syntax","subbranchId":"inversion-after-negative-limiting","masteryConceptId":"grammar-concept-inversion-after-negative-limiting","prerequisites":["grammar-d20-advanced-advanced-passive-reporting"],"wizardSessionId":"grammar-d20-advanced-inversion-wiz","testSessionId":"grammar-d20-advanced-inversion-test","blocks":[{"type":"explanation","titleEn":"Inversion After Negative or Limiting Expressions","en":"When a negative/limiting adverbial (never, rarely, not only, no sooner) begins a sentence, the auxiliary verb inverts with the subject for emphasis.","ps":"کله چې د نفي/محدودوونکی قید (never, rarely, not only, no sooner) جمله پیلوي، د ټینګار لپاره مرستیال فعل له فاعل سره ځای بدلوي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Never have I seen such courage.","ps":"زه هیڅکله داسې زړورتیا نه ده لیدلې."},{"en":"Rarely does he arrive on time.","ps":"هغه ډېر لږ کله په وخت راځي."},{"en":"Not only did she pass, she got the highest score.","ps":"هغه یوازې بریالۍ نشوه، بلکه تر ټولو لوړه نمره یې واخیسته."},{"en":"No sooner had he arrived than the meeting started.","ps":"لا هغه نه و راورسیدلی چې غونډه پیل شوه."},{"en":"Under no circumstances should you sign that.","ps":"په هیڅ حالت کې دې دا ولاسلیک نه کړي."},{"en":"Little did she know what awaited her.","ps":"هغې لږ پوهیده چې څه به یې انتظار کوي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Never I have seen such courage. | Right: Never have I seen such courage. | The auxiliary verb must come before the subject after the negative opener.","ps":"د نفي پیل کوونکي وروسته مرستیال فعل باید له فاعل مخکې راشي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-hedging-softening","titleEn":"Hedging and Softening Language","titlePs":"د محتاطانه او نرمولو ژبه","levelNumber":null,"acceptedLevelId":"advanced","branchId":"pragmatics","subbranchId":"hedging-and-softening","masteryConceptId":"grammar-concept-hedging-and-softening","prerequisites":["grammar-d20-advanced-inversion"],"wizardSessionId":"grammar-d20-advanced-hedging-softening-wiz","testSessionId":"grammar-d20-advanced-hedging-softening-test","blocks":[{"type":"explanation","titleEn":"Hedging and Softening Language","en":"Use hedging language (it seems, tends to, might argue, arguably, to some extent) to soften claims and sound less absolute.","ps":"د ادعاوو نرمولو او لږ بشپړ ښکارېدو لپاره د محتاط ژبه وکاروئ (it seems, tends to, might argue, arguably, to some extent)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"It seems that the results were not as expected.","ps":"داسې ښکاري چې پایلې د تمې سره سم نه وې."},{"en":"This approach tends to work better in smaller teams.","ps":"دا لاره د کوچنیو ډلو کې ښه کار کوي."},{"en":"One might argue that the policy needs revision.","ps":"یو کس دا ادعا کولی شي چې پالیسي بیاکتنې ته اړتیا لري."},{"en":"The plan was, arguably, too ambitious.","ps":"پلان، شاید، ډېر لوی و."},{"en":"To some extent, the criticism is fair.","ps":"یو حد پورې، نیوکه سمه ده."},{"en":"It could be argued that more time was needed.","ps":"دا ویل کیدی شي چې نور وخت ته اړتیا وه."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The plan was too ambitious. (stated as absolute fact without evidence) | Right: The plan was, arguably, too ambitious. | Formal/academic register generally avoids unqualified absolute claims — hedging shows appropriate caution.","ps":"رسمي ژبه معمولا له بشپړو ادعاوو ډډه کوي، محتاط ژبه مناسب احتیاط ښیي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-participle-clauses","titleEn":"Participle Clauses","titlePs":"د مفعول فقرې","levelNumber":null,"acceptedLevelId":"advanced","branchId":"syntax","subbranchId":"participle-clauses","masteryConceptId":"grammar-concept-participle-clauses","prerequisites":["grammar-d20-advanced-hedging-softening"],"wizardSessionId":"grammar-d20-advanced-participle-clauses-wiz","testSessionId":"grammar-d20-advanced-participle-clauses-test","blocks":[{"type":"explanation","titleEn":"Participle Clauses","en":"Participle clauses (-ing or -ed) replace longer clauses with a subordinating word, making sentences more concise and formal.","ps":"د مفعول فقرې (-ing یا -ed) اوږدې فقرې د تابع کوونکي کلمې سره بدلوي، جملې لنډې او رسمي کوي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Having finished the report, she left the office. (= After she had finished)","ps":"راپور یې بشپړ کړی وو، دفتر یې پریښود."},{"en":"Written in 1990, the novel remains popular. (= Which was written)","ps":"چې په ۱۹۹۰ کال کې لیکل شوی و، دا ناول لا هم مشهور دی."},{"en":"Feeling exhausted, he decided to rest. (= Because he felt exhausted)","ps":"ستړی احساس یې کاوه، ارام کولو ته یې پرېکړه وکړه."},{"en":"Not knowing what to say, she stayed silent. (= Because she did not know)","ps":"نه پوهیده چې څه ووایي، غلې پاتې شوه."},{"en":"Given the circumstances, the decision was reasonable. (= Considering)","ps":"د حالاتو په پام کې نیولو سره، پرېکړه معقوله وه."},{"en":"Standing at the door, he waited for her answer. (= While he stood)","ps":"د دروازې پر مخ ولاړ و، د هغې د ځواب انتظار یې باسه."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Having finish the report, she left. | Right: Having finished the report, she left. | Perfect participle clauses use having + past participle, not the base verb.","ps":"بشپړ مفعول فقرې having + تېر مفعول کاروي، نه اصلي فعل."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-reduced-relative-clauses","titleEn":"Reduced Relative Clauses","titlePs":"کمې شوې وابسته فقرې","levelNumber":null,"acceptedLevelId":"advanced","branchId":"relative-clauses","subbranchId":"reduced-relative-clauses","masteryConceptId":"grammar-concept-reduced-relative-clauses","prerequisites":["grammar-d20-advanced-participle-clauses"],"wizardSessionId":"grammar-d20-advanced-reduced-relative-clauses-wiz","testSessionId":"grammar-d20-advanced-reduced-relative-clauses-test","blocks":[{"type":"explanation","titleEn":"Reduced Relative Clauses","en":"Active reduced clauses drop who/which + be and use -ing. Passive reduced clauses drop who/which + be and use the past participle.","ps":"فعال کمې شوې فقرې who/which + be غورځوي او -ing کاروي. مجهول کمې شوې فقرې who/which + be غورځوي او تېر مفعول کاروي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The man standing near the door is my uncle. (= who is standing)","ps":"هغه سړی چې د دروازې تر څنګ ولاړ دی زما تره دی."},{"en":"The report submitted yesterday was rejected. (= which was submitted)","ps":"هغه راپور چې پرون سپارل شوی و رد شو."},{"en":"Students studying abroad often face challenges. (= who are studying)","ps":"هغه زده کوونکي چې بهر لولي معمولا ستونزو سره مخ کیږي."},{"en":"The documents required for the visa are listed below. (= which are required)","ps":"هغه اسناد چې د ویزې لپاره اړین دي لاندې لیست شوي دي."},{"en":"Anyone wishing to attend must register first. (= who wishes)","ps":"هر څوک چې غواړي ګډون وکړي باید لومړی ثبت نام وکړي."},{"en":"The car parked outside belongs to my brother. (= which was parked)","ps":"هغه موټر چې بهر ولاړ دی زما د ورور دی."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The man stand near the door is my uncle. | Right: The man standing near the door is my uncle. | Active reduced clauses need the -ing form, not the base verb.","ps":"فعال کمې شوې فقرې -ing بڼه غواړي، نه اصلي فعل."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-modal-meaning","titleEn":"Advanced Modal Meaning","titlePs":"پرمختللی د مودل مانا","levelNumber":null,"acceptedLevelId":"advanced","branchId":"modals","subbranchId":"advanced-modal-meaning","masteryConceptId":"grammar-concept-advanced-modal-meaning","prerequisites":["grammar-d20-advanced-reduced-relative-clauses"],"wizardSessionId":"grammar-d20-advanced-modal-meaning-wiz","testSessionId":"grammar-d20-advanced-modal-meaning-test","blocks":[{"type":"explanation","titleEn":"Advanced Modal Meaning","en":"Modals carry subtle formal shades: shall (formal obligation/offer), needn't have (unnecessary action taken), should have (missed obligation).","ps":"مودل افعال نازک رسمي رنګ لري: shall (رسمي دنده/وړاندیز)، needn't have (غیر اړین ترسره شوی کار)، should have (له لاسه ورکړل شوې دنده)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"All applicants shall submit documents by Friday. (formal obligation)","ps":"ټول غوښتونکي باید تر جمعې پورې اسناد وسپاري. (رسمي دنده)"},{"en":"You needn't have brought a gift. (unnecessary — but you did)","ps":"اړتیا نه وه چې ډالۍ راوړې. (غیر اړین و — خو دې وکړل)"},{"en":"You should have called before visiting. (missed obligation, criticism)","ps":"ستا پکار وه چې د لیدو مخکې زنګ ووهې. (له لاسه ورکړل شوې دنده)"},{"en":"Shall we begin the meeting? (formal offer/suggestion)","ps":"آیا غونډه پیل کړو؟ (رسمي وړاندیز)"},{"en":"She needn't worry about the results. (not necessary)","ps":"هغې ته اړتیا نه ده چې د پایلو په اړه پرېشانه شي."},{"en":"They shouldn't have left without informing us.","ps":"دوی نه باید موږ ته د خبرولو پرته تللي وای."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: You needn't have bring a gift. | Right: You needn't have brought a gift. | needn't have requires the past participle, not the base verb.","ps":"needn't have تېر مفعول غواړي، نه اصلي فعل."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-cleft-pseudo-cleft","titleEn":"Cleft and Pseudo-Cleft Sentences","titlePs":"د ویشلو او شبه ویشلو جملې","levelNumber":null,"acceptedLevelId":"advanced","branchId":"syntax","subbranchId":"cleft-pseudo-cleft-sentences","masteryConceptId":"grammar-concept-cleft-pseudo-cleft-sentences","prerequisites":["grammar-d20-advanced-modal-meaning"],"wizardSessionId":"grammar-d20-advanced-cleft-pseudo-cleft-wiz","testSessionId":"grammar-d20-advanced-cleft-pseudo-cleft-test","blocks":[{"type":"explanation","titleEn":"Cleft and Pseudo-Cleft Sentences","en":"Cleft sentences (It was X who/that...) and pseudo-cleft (What X did was...) emphasize a specific part of the sentence.","ps":"د ویشلو جملې (It was X who/that...) او شبه ویشلو (What X did was...) د جملې یوه ځانګړې برخه ټینګاروي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"It was Ahmad who solved the problem. (emphasizes Ahmad)","ps":"دا احمد و چې ستونزه یې حل کړه."},{"en":"It was in 2015 that the school opened.","ps":"دا په ۲۰۱۵ کال کې و چې ښوونځی پرانیستل شو."},{"en":"What she needs is more time.","ps":"هغه څه چې هغې ته اړتیا لري نور وخت دی."},{"en":"What surprised me was his honesty.","ps":"هغه څه چې زه یې حیران کړم د هغه رښتینوالی و."},{"en":"What we did was rebuild the entire system.","ps":"هغه څه چې موږ وکړل ټول سیستم مو بیا جوړ کړ."},{"en":"It is hard work that leads to success.","ps":"دا سخت کار دی چې بریالیتوب ته رسوي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: It was Ahmad who he solved the problem. | Right: It was Ahmad who solved the problem. | Do not repeat the subject with a pronoun after who in a cleft sentence.","ps":"د ویشلو جملې کې د who وروسته فاعل بیا د ضمیر سره مه تکراروئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-ellipsis-substitution","titleEn":"Ellipsis and Substitution","titlePs":"حذف او ځای ناستی","levelNumber":null,"acceptedLevelId":"advanced","branchId":"cohesion","subbranchId":"ellipsis-and-substitution","masteryConceptId":"grammar-concept-ellipsis-and-substitution","prerequisites":["grammar-d20-advanced-cleft-pseudo-cleft"],"wizardSessionId":"grammar-d20-advanced-ellipsis-substitution-wiz","testSessionId":"grammar-d20-advanced-ellipsis-substitution-test","blocks":[{"type":"explanation","titleEn":"Ellipsis and Substitution","en":"Ellipsis omits repeated words when meaning is clear from context. Substitution replaces them with one/do so/so to avoid repetition.","ps":"حذف تکراري کلمات غورځوي کله چې مانا له متن نه روښانه وي. ځای ناستی د تکرار ډډې لپاره one/do so/so کاروي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I wanted to go, but I couldn't [go]. (ellipsis)","ps":"زه غوښتل لاړ شم، خو ونشوای. (حذف)"},{"en":"A: Are you coming? B: I hope so. (substitution)","ps":"الف: راځې؟ ب: امید لرم چې هو."},{"en":"She passed the exam and so did he. (substitution)","ps":"هغه ازموینه تیره کړه او هغه هم داسې وکړل."},{"en":"I have two pens; do you have one? (substitution)","ps":"زه دوه قلمونه لرم؛ ته یو لرې؟"},{"en":"He said he would help, and he did [help]. (ellipsis)","ps":"هغه ویل چې به مرسته وکړي، او یې وکړه. (حذف)"},{"en":"A: Did she finish? B: I believe so.","ps":"الف: بشپړ یې کړ؟ ب: زه باور لرم چې هو."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I hope it. (attempting substitution) | Right: I hope so. | The substitute for a whole clause is usually so, not it.","ps":"د بشپړې فقرې ځای ناستی معمولا so دی، نه it."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-emphasis-fronting","titleEn":"Emphasis and Fronting","titlePs":"ټینګار او مخکې راوړل","levelNumber":null,"acceptedLevelId":"advanced","branchId":"syntax","subbranchId":"emphasis-and-fronting","masteryConceptId":"grammar-concept-emphasis-and-fronting","prerequisites":["grammar-d20-advanced-ellipsis-substitution"],"wizardSessionId":"grammar-d20-advanced-emphasis-fronting-wiz","testSessionId":"grammar-d20-advanced-emphasis-fronting-test","blocks":[{"type":"explanation","titleEn":"Emphasis and Fronting","en":"Fronting moves an element to the start of the sentence for emphasis, often requiring inversion.","ps":"مخکې راوړل د ټینګار لپاره یو عنصر جملې پیل ته وړي، ډېری وخت وارونتوب ته اړتیا لري."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Such was her determination that nothing could stop her.","ps":"د هغې ډاډ داسې و چې هیڅ شی یې نشوای درولی."},{"en":"Down came the rain, heavy and sudden.","ps":"باران راښکته شو، درانه او ناڅاپي."},{"en":"Gone are the days when we could travel freely.","ps":"هغه ورځې تېرې شوې کله چې موږ کولی شوای آزادانه سفر وکړو."},{"en":"On no account should this door be left open.","ps":"په هیڅ حالت کې دا دروازه پرانستې پاتې نه شي."},{"en":"Only after the meeting did she explain her decision.","ps":"یوازې د غونډې وروسته یې خپله پرېکړه تشریح کړه."},{"en":"What he said next surprised everyone.","ps":"هغه چې بیا یې وویل ټول حیران کړل."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Only after the meeting she explained her decision. | Right: Only after the meeting did she explain her decision. | A fronted only-phrase requires subject-auxiliary inversion.","ps":"مخکې شوی only جمله د فاعل-مرستیال وارونتوب غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-complex-noun-phrases","titleEn":"Complex Noun Phrases","titlePs":"پیچلي نومي جملات","levelNumber":null,"acceptedLevelId":"advanced","branchId":"noun-phrases","subbranchId":"complex-noun-phrases","masteryConceptId":"grammar-concept-complex-noun-phrases","prerequisites":["grammar-d20-advanced-emphasis-fronting"],"wizardSessionId":"grammar-d20-advanced-complex-noun-phrases-wiz","testSessionId":"grammar-d20-advanced-complex-noun-phrases-test","blocks":[{"type":"explanation","titleEn":"Complex Noun Phrases","en":"Advanced noun phrases stack modifiers: determiner + quantifier + adjective(s) + noun + prepositional phrase/relative clause.","ps":"پرمختللي نومي جملات د تعدیلوونکو ډله ییز کول: ټاکوونکی + اندازه + صفت(ونه) + نوم + حرفي جمله/وابسته فقره."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The three newly published research papers on climate change","ps":"درې تازه خپرې شوې د اقلیمي بدلون په اړه څیړنیزې مقالې"},{"en":"A remarkably well-organized international conference","ps":"یو د پام وړ ښه سازمان شوی نړیوال کنفرانس"},{"en":"The growing number of students applying for scholarships","ps":"د بورس لپاره غوښتنه کوونکو زده کوونکو زیاتیدونکی شمېر"},{"en":"Several long-standing disputes over land ownership","ps":"د ځمکې مالکیت پر سر څو اوږدمهاله شخړې"},{"en":"A comprehensive report detailing the project's progress","ps":"یو بشپړ راپور چې د پروژې پرمختګ تشریح کوي"},{"en":"The many challenges facing rural communities today","ps":"هغه ډېری ننګونې چې نن ورځ کلیوالی ټولنو سره مخ دي"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: the newly three published papers | Right: the three newly published papers | Number/quantifier normally precedes other modifiers in a stacked noun phrase.","ps":"شمېره/اندازه معمولا د نورو تعدیلوونکو مخکې راځي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-register-transformation","titleEn":"Formal vs Informal Register Transformation","titlePs":"رسمي بمقابل غیر رسمي بڼې بدلون","levelNumber":null,"acceptedLevelId":"advanced","branchId":"register","subbranchId":"formal-informal-register-transformation","masteryConceptId":"grammar-concept-formal-informal-register-transformation","prerequisites":["grammar-d20-advanced-complex-noun-phrases"],"wizardSessionId":"grammar-d20-advanced-register-transformation-wiz","testSessionId":"grammar-d20-advanced-register-transformation-test","blocks":[{"type":"explanation","titleEn":"Formal vs Informal Register Transformation","en":"Transform informal phrasing (contractions, phrasal verbs, simple vocabulary) into formal equivalents (full forms, Latinate verbs, precise vocabulary).","ps":"غیر رسمي بڼه (لنډیزونه، جملوي افعال، ساده لغتونه) رسمي معادل ته بدلوئ (بشپړې بڼې، دقیق لغتونه)."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Informal: We need to look into this. Formal: We need to investigate this matter.","ps":"غیر رسمي: موږ باید دې ته وګورو. رسمي: موږ باید دا موضوع وڅیړو."},{"en":"Informal: Can't make it tomorrow. Formal: I am unable to attend tomorrow.","ps":"غیر رسمي: سبا نشم راتللی. رسمي: زه سبا د ګډون توان نه لرم."},{"en":"Informal: The results were kind of surprising. Formal: The results were somewhat unexpected.","ps":"غیر رسمي: پایلې یو څه حیرانوونکې وې. رسمي: پایلې یو څه غیر متوقعې وې."},{"en":"Informal: They put off the meeting. Formal: They postponed the meeting.","ps":"غیر رسمي: دوی غونډه وځنډول. رسمي: دوی غونډه وځنډوله."},{"en":"Informal: We'll get back to you soon. Formal: We will respond to you shortly.","ps":"غیر رسمي: موږ به ژر ورشو. رسمي: موږ به ژر ځواب درکړو."},{"en":"Informal: The plan didn't work out. Formal: The plan was unsuccessful.","ps":"غیر رسمي: پلان ونه شو. رسمي: پلان ناکام و."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: We need to investigate into this matter. (mixing formal verb with informal preposition) | Right: We need to investigate this matter. | investigate does not take into — mixing registers creates an unnatural hybrid.","ps":"investigate into نه اخلي — د بڼو ګډول غیر طبیعي جوړوي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-unreal-past","titleEn":"Unreal Past Structures","titlePs":"غیر واقعي تېر جوړښتونه","levelNumber":null,"acceptedLevelId":"advanced","branchId":"unreal-meaning","subbranchId":"unreal-past-structures","masteryConceptId":"grammar-concept-unreal-past-structures","prerequisites":["grammar-d20-advanced-register-transformation"],"wizardSessionId":"grammar-d20-advanced-unreal-past-wiz","testSessionId":"grammar-d20-advanced-unreal-past-test","blocks":[{"type":"explanation","titleEn":"Unreal Past Structures","en":"Structures like it's time, would rather, and if only use a past-tense form to express an unreal present meaning.","ps":"د it's time، would rather، او if only ډول جوړښتونه د غیر واقعي اوسني مانا بیانولو لپاره تېر مهال بڼه کاروي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"It's time we left. (we should leave now)","ps":"وخت دی چې لاړ شو."},{"en":"I would rather you didn't smoke here.","ps":"زه غواړم چې دلته سیګرټ ونه څکوې."},{"en":"If only I had more patience!","ps":"کاش چې زما سره ډېر صبر وای!"},{"en":"It's high time the government addressed this issue.","ps":"وخت رارسیدلی چې حکومت دا مسله حل کړي."},{"en":"I'd rather we discussed this later.","ps":"زه غواړم چې دا وروسته وغږیږو."},{"en":"If only he listened to advice!","ps":"کاش چې سلا واورېدلای!"}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: It's time we leave. | Right: It's time we left. | It's time uses a past-tense verb form to express present unreal urgency.","ps":"It's time د اوسني غیر واقعي بیړې بیانولو لپاره تېره بڼه کاروي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-stance-qualification","titleEn":"Stance and Qualification","titlePs":"دریځ او شرطي کول","levelNumber":null,"acceptedLevelId":"advanced","branchId":"pragmatics","subbranchId":"stance-and-qualification","masteryConceptId":"grammar-concept-stance-and-qualification","prerequisites":["grammar-d20-advanced-unreal-past"],"wizardSessionId":"grammar-d20-advanced-stance-qualification-wiz","testSessionId":"grammar-d20-advanced-stance-qualification-test","blocks":[{"type":"explanation","titleEn":"Stance and Qualification","en":"Use stance markers (clearly, undoubtedly, presumably, apparently) and qualifiers (in most cases, broadly speaking) to signal certainty level and scope.","ps":"د دریځ نښې (clearly, undoubtedly, presumably, apparently) او شرطي کوونکي (in most cases, broadly speaking) وکاروئ ترڅو د ډاډ کچه او ساحه وښایاست."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Clearly, the policy needs revision.","ps":"روښانه ده چې پالیسي بیاکتنې ته اړتیا لري."},{"en":"Presumably, they will announce the decision next week.","ps":"ښکاره ده چې دوی به بله اونۍ پرېکړه اعلان کړي."},{"en":"Broadly speaking, the results support the theory.","ps":"په پراخه توګه، پایلې تیوري تایید کوي."},{"en":"In most cases, early treatment leads to better outcomes.","ps":"په ډېری قضیو کې، وختي درملنه ښه پایلې لري."},{"en":"Apparently, the meeting has been postponed.","ps":"داسې ښکاري چې غونډه وځنډول شوه."},{"en":"Undoubtedly, this represents significant progress.","ps":"بې له شکه، دا د پام وړ پرمختګ استازیتوب کوي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Clearly the policy needs revision it. | Right: Clearly, the policy needs revision. | Do not duplicate the object with a redundant pronoun.","ps":"مفعول د ضمیر سره مه تکراروئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-precise-reformulation","titleEn":"Precise Reformulation","titlePs":"دقیق بیا جوړونه","levelNumber":null,"acceptedLevelId":"advanced","branchId":"cohesion","subbranchId":"precise-reformulation","masteryConceptId":"grammar-concept-precise-reformulation","prerequisites":["grammar-d20-advanced-stance-qualification"],"wizardSessionId":"grammar-d20-advanced-precise-reformulation-wiz","testSessionId":"grammar-d20-advanced-precise-reformulation-test","blocks":[{"type":"explanation","titleEn":"Precise Reformulation","en":"Reformulate a sentence using markers like in other words, that is to say, put differently, to clarify or restate precisely.","ps":"د روښانتیا یا دقیق بیا بیانولو لپاره جمله د in other words, that is to say, put differently نښو سره بیا جوړه کړئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The results were inconclusive; in other words, we cannot draw a firm conclusion.","ps":"پایلې غیر پرېکړن وې؛ په بله وینا، موږ نشو کولی قطعي پایله وباسو."},{"en":"The proposal was rejected — that is to say, it needs significant revision.","ps":"وړاندیز رد شو — یعنې، د پام وړ بیاکتنې ته اړتیا لري."},{"en":"Put differently, the two studies reached opposite conclusions.","ps":"په بل عبارت، دواړو مطالعو مخالفې پایلې ترلاسه کړې."},{"en":"In simpler terms, the process reduces waste significantly.","ps":"په ساده الفاظو، دا پروسه ضایعات د پام وړ کموي."},{"en":"To put it another way, cost was the deciding factor.","ps":"په بل ډول ووایو، لګښت پرېکړن فکتور و."},{"en":"This means, essentially, that further research is needed.","ps":"دا مانا لري چې، اساسا، نور تحقیق ته اړتیا ده."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: In other words we cannot draw a firm conclusion the results were inconclusive. | Right: The results were inconclusive; in other words, we cannot draw a firm conclusion. | The reformulation marker should follow, not replace, the logical order of original then restatement.","ps":"د بیا جوړونې نښه باید له اصلي جملې وروسته راشي، نه یې ځای ناستی شي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-advanced-cohesion-complex-sentences","titleEn":"Advanced Cohesion Across Complex Sentences","titlePs":"د پیچلو جملو ترمنځ پرمختللی نښلون","levelNumber":null,"acceptedLevelId":"advanced","branchId":"cohesion","subbranchId":"advanced-cohesion-across-complex-sentences","masteryConceptId":"grammar-concept-advanced-cohesion-across-complex-sentences","prerequisites":["grammar-d20-advanced-precise-reformulation"],"wizardSessionId":"grammar-d20-advanced-cohesion-complex-sentences-wiz","testSessionId":"grammar-d20-advanced-cohesion-complex-sentences-test","blocks":[{"type":"explanation","titleEn":"Advanced Cohesion Across Complex Sentences","en":"Maintain cohesion across sentences using consistent reference chains (pronouns, synonyms, this/that + noun) and logical connectors, avoiding repetition and ambiguity.","ps":"د جملو ترمنځ نښلون د ثابتو راجع کولو زنځیرونو (ضمیرونه، مترادفات، this/that + نوم) او منطقي نښلوونکو سره وساتئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The committee reviewed the proposal. This document outlined three key changes.","ps":"کمېټې وړاندیز وکتلو. دې سند درې مهمې بدلونونه ښودلې."},{"en":"Researchers studied the data for a decade. Their findings revealed a clear pattern.","ps":"څیړونکو یو لسیزه معلومات وڅیړل. د دوی موندنو یوه روښانه بڼه ښکاره کړه."},{"en":"The first proposal focused on cost. The latter emphasized quality instead.","ps":"لومړی وړاندیز په لګښت تمرکز درلود. وروستی یې پر ځای کیفیت ته ټینګار وکړ."},{"en":"Climate change affects agriculture directly. This, in turn, threatens food security.","ps":"اقلیمي بدلون مستقیم په کرنه اغیزه کوي. دا، په خپل وار، د خواړو خوندیتوب ګواښوي."},{"en":"The policy was controversial. Nevertheless, it was implemented nationwide.","ps":"پالیسي جنجالي وه. سره له دې هم، هېواد کچه پلي شوه."},{"en":"Several factors contributed to the delay. Chief among these was funding shortage.","ps":"څو فکتورونو ځنډ رامنځته کړ. ترټولو مهم یې د بودیجې کمښت و."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The committee reviewed the proposal. The committee repeated document outlined three key changes. | Right: The committee reviewed the proposal. This document outlined three key changes. | Repeating the same noun phrase across sentences reduces cohesion — vary reference using pronouns, synonyms, or this/that.","ps":"د ورته نومي جملې تکرار نښلون کموي، د ضمیرونو یا مترادفاتو سره یې بدل کړئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-nominalization","titleEn":"Nominalization","titlePs":"اسمي کول","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"nominalization","masteryConceptId":"grammar-concept-nominalization","prerequisites":[],"wizardSessionId":"grammar-d20-academic-nominalization-wiz","testSessionId":"grammar-d20-academic-nominalization-test","blocks":[{"type":"explanation","titleEn":"Nominalization","en":"Nominalization converts verbs/adjectives into nouns (analyze→analysis, decide→decision) to create a more formal, compact academic style.","ps":"اسمي کول افعال/صفتونه نومونو ته اړوي (analyze→analysis, decide→decision) ترڅو رسمي، کثیف اکادمیک بڼه رامنځته شي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"They analyzed the data. → Their analysis of the data revealed...","ps":"دوی معلومات وڅیړل. → د دوی د معلوماتو تحلیل ښکاره کړ..."},{"en":"The committee decided quickly. → The committee's decision was made quickly.","ps":"کمېټې ژر پرېکړه وکړه. → د کمېټې پرېکړه ژر وشوه."},{"en":"The results were significant. → The significance of the results...","ps":"پایلې مهمې وې. → د پایلو اهمیت..."},{"en":"The government implemented the policy. → The implementation of the policy...","ps":"حکومت پالیسي پلي کړه. → د پالیسي پلي کول..."},{"en":"Researchers assessed the risk. → An assessment of the risk was conducted.","ps":"څیړونکو خطر وارزاوه. → د خطر ارزونه ترسره شوه."},{"en":"The company grew rapidly. → The rapid growth of the company...","ps":"شرکت په چټکۍ وده وکړه. → د شرکت چټکه وده..."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The analysis of the data revealed by them. | Right: Their analysis of the data revealed... | A nominalized clause needs a possessive or of-phrase, not a stray passive tail.","ps":"اسمي شوې فقره ملکیتي یا of-جمله غواړي، نه ناڅاپي مجهول لکۍ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-reporting-verbs","titleEn":"Reporting Verbs and Reporting Patterns","titlePs":"رپوټ کوونکي افعال او بڼې","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"reporting-verbs-and-patterns","masteryConceptId":"grammar-concept-reporting-verbs-and-patterns","prerequisites":["grammar-d20-academic-nominalization"],"wizardSessionId":"grammar-d20-academic-reporting-verbs-wiz","testSessionId":"grammar-d20-academic-reporting-verbs-test","blocks":[{"type":"explanation","titleEn":"Reporting Verbs and Reporting Patterns","en":"Academic reporting verbs (argue, suggest, claim, demonstrate, note) show the writer's stance toward a cited source more precisely than say.","ps":"اکادمیک رپوټ کوونکي افعال (argue, suggest, claim, demonstrate, note) د لیکوال دریځ د یادونې شوي سرچینې په اړه ډېر دقیق ښیي تر say."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Smith (2019) argues that the policy failed.","ps":"سمیت (۲۰۱۹) ادعا کوي چې پالیسي ناکامه شوه."},{"en":"The data suggests a strong correlation.","ps":"معلومات یوه قوي اړیکه وړاندیز کوي."},{"en":"The author claims this approach is superior.","ps":"لیکوال ادعا کوي چې دا لاره غوره ده."},{"en":"The study demonstrates a clear pattern.","ps":"مطالعه یوه روښانه بڼه ښیي."},{"en":"Researchers note that further study is required.","ps":"څیړونکي یادونه کوي چې نور مطالعه اړینه ده."},{"en":"Jones (2020) contends that the theory is outdated.","ps":"جونز (۲۰۲۰) استدلال کوي چې تیوري زړه شوې ده."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Smith (2019) says that the policy failed, which proves it completely. | Right: Smith (2019) argues that the policy failed. | Choose the reporting verb that matches the actual strength of the claim — argues signals a debatable position, not a proven fact.","ps":"هغه رپوټ کوونکی فعل غوره کړئ چې د ادعا ریښتینې کچې سره سمون ولري."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-cautious-claims","titleEn":"Cautious Claims and Calibrated Certainty","titlePs":"محتاطانه ادعاوې او تنظیم شوی ډاډ","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"cautious-claims-calibrated-certainty","masteryConceptId":"grammar-concept-cautious-claims-calibrated-certainty","prerequisites":["grammar-d20-academic-reporting-verbs"],"wizardSessionId":"grammar-d20-academic-cautious-claims-wiz","testSessionId":"grammar-d20-academic-cautious-claims-test","blocks":[{"type":"explanation","titleEn":"Cautious Claims and Calibrated Certainty","en":"Calibrate certainty with words like may, appears to, is likely to, tends to, rather than overstating findings as absolute fact.","ps":"د ډاډ کچه د may, appears to, is likely to, tends to کلماتو سره تنظیم کړئ، پرځای دې چې موندنې مطلقې ادعا کړئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"The results may indicate a link between diet and health.","ps":"پایلې ممکن د خوراک او روغتیا ترمنځ اړیکه وښیي."},{"en":"This finding appears to support the hypothesis.","ps":"دا موندنه فرضیه ملاتړ کوي داسې ښکاري."},{"en":"Such policies are likely to reduce costs over time.","ps":"داسې پالیسۍ به احتمالا په مرور وخت لګښتونه کموي."},{"en":"Smaller organizations tend to adapt faster.","ps":"کوچنۍ سازمانونه معمولا ژر عیاروي."},{"en":"The evidence suggests, though does not confirm, a causal relationship.","ps":"شواهد وړاندیز کوي، خو تایید نه کوي، د سبب اړیکه."},{"en":"It is possible that other factors also contributed.","ps":"ممکنه ده چې نور فکتورونو هم مرسته کړې وي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The results prove that diet causes better health. | Right: The results may indicate a link between diet and health. | Correlational data cannot support an absolute causal claim — calibrate the certainty to match the evidence.","ps":"د اړیکو معلومات مطلق سببي ادعا نشي ملاتړ کولی، ډاډ باید له شواهدو سره سمون ولري."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-complex-clause-control","titleEn":"Complex Clause Control (Academic)","titlePs":"د پیچلو فقرو کنترول (اکادمیک)","levelNumber":null,"acceptedLevelId":"academic","branchId":"syntax","subbranchId":"complex-clause-control-academic","masteryConceptId":"grammar-concept-complex-clause-control-academic","prerequisites":["grammar-d20-academic-cautious-claims"],"wizardSessionId":"grammar-d20-academic-complex-clause-control-wiz","testSessionId":"grammar-d20-academic-complex-clause-control-test","blocks":[{"type":"explanation","titleEn":"Complex Clause Control (Academic)","en":"Academic writing chains multiple subordinate clauses precisely, controlling which idea is main and which is subordinate.","ps":"اکادمیک لیکنه ډېری تابع فقرې په دقت سره نښلوي، کنترولوي چې کوم نظر اصلي دی او کوم تابع دی."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Although the sample size was limited, the findings, which align with prior research, remain informative.","ps":"که څه هم نمونه محدوده وه، موندنې، چې له تېرو څیړنو سره سمون لري، لا هم معلوماتي دي."},{"en":"Given that resources were constrained, the team, having prioritized key objectives, achieved notable results.","ps":"له دې چې سرچینې محدودې وې، ټیم، مهمو موخو ته لومړیتوب ورکړي وو، د پام وړ پایلې ترلاسه کړې."},{"en":"While the theory explains most cases, it fails to account for outliers that deviate significantly.","ps":"پداسې حال کې چې تیوري ډېری قضیې تشریح کوي، د هغو غیر معمولو قضیو حساب نه ورکوي چې د پام وړ توپیر لري."},{"en":"Because the variables were interrelated, isolating a single cause proved difficult.","ps":"ځکه چې متغیرات ترمنځ اړیکه درلوده، د یوازینۍ لامل بیلول ستونزمن ثابته شوه."},{"en":"The policy, though controversial when introduced, has since gained broad support.","ps":"پالیسي، که څه هم د معرفي پر مهال جنجالي وه، تر هغه راهیسې پراخ ملاتړ ترلاسه کړی."},{"en":"Researchers who examined the long-term effects found results that contradicted earlier assumptions.","ps":"هغه څیړونکي چې اوږدمهاله اغیزې یې وڅیړلې، هغه پایلې ومونده چې له مخکینیو انګیرنو سره مخالفې وې."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Although the sample size was limited. The findings remain informative. | Right: Although the sample size was limited, the findings remain informative. | An although-clause must be joined to the main clause, not punctuated as a separate sentence.","ps":"although فقره باید له اصلي فقرې سره ونښلي، نه د جلا جملې په توګه."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-cohesion","titleEn":"Academic Cohesion","titlePs":"اکادمیک نښلون","levelNumber":null,"acceptedLevelId":"academic","branchId":"cohesion","subbranchId":"academic-cohesion","masteryConceptId":"grammar-concept-academic-cohesion","prerequisites":["grammar-d20-academic-complex-clause-control"],"wizardSessionId":"grammar-d20-academic-cohesion-wiz","testSessionId":"grammar-d20-academic-cohesion-test","blocks":[{"type":"explanation","titleEn":"Academic Cohesion","en":"Use topic sentences, signposting language (this section examines, the following discussion), and consistent terminology to guide the reader through an academic text.","ps":"د موضوع جملات، لارښود ژبه (this section examines, the following discussion)، او ثابت اصطلاحات وکاروئ ترڅو لوستونکی د اکادمیک متن له لارې لارښوونه وکړي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"This section examines the causes of the decline.","ps":"دا برخه د راکمېدو لاملونه ارزوي."},{"en":"The following discussion turns to the implications of these findings.","ps":"راتلونکی بحث دې موندنو پایلو ته اړوي."},{"en":"As noted above, the sample was limited to urban areas.","ps":"لکه پورته یادونه، نمونه ښاري سیمو پورې محدوده وه."},{"en":"Having established the theoretical framework, we now turn to the data.","ps":"د نظري چوکاټ له ټاکلو وروسته، اوس معلوماتو ته اړوو."},{"en":"The remainder of this paper is organized as follows.","ps":"د دې مقالې پاتې برخه په لاندې ډول تنظیم شوې ده."},{"en":"In summary, the evidence points toward a consistent trend.","ps":"په لنډ ډول، شواهد یوه ثابته رجحان ته اشاره کوي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: This section examines the causes. Now let's talk about something else without connection. | Right: This section examines the causes of the decline, before turning to potential solutions. | Academic cohesion requires explicit transitions, not abrupt unmarked topic shifts.","ps":"اکادمیک نښلون واضح انتقال غواړي، نه ناڅاپي بدلون."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-argument-structure","titleEn":"Argument Structure","titlePs":"د دلیل جوړښت","levelNumber":null,"acceptedLevelId":"academic","branchId":"argumentation","subbranchId":"argument-structure","masteryConceptId":"grammar-concept-argument-structure","prerequisites":["grammar-d20-academic-cohesion"],"wizardSessionId":"grammar-d20-academic-argument-structure-wiz","testSessionId":"grammar-d20-academic-argument-structure-test","blocks":[{"type":"explanation","titleEn":"Argument Structure","en":"A formal academic argument states a claim, supports it with evidence, addresses a counterargument, and concludes.","ps":"رسمي اکادمیک دلیل یو ادعا بیانوي، د شواهدو سره یې ملاتړ کوي، مخالف دلیل ته ځواب ورکوي، او پایله اخلي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Claim: Remote work improves productivity.","ps":"ادعا: لرې کار د کاري ظرفیت ښه کوي."},{"en":"Evidence: A 2021 study found a 13% increase in output among remote workers.","ps":"شواهد: د ۲۰۲۱ کال مطالعې د لرې کارکوونکو کې ۱۳٪ زیاتوالی وموند."},{"en":"Counterargument: Critics argue that collaboration suffers without in-person contact.","ps":"مخالف دلیل: منتقدین ادعا کوي چې همغږي پرته له مستقیمې اړیکې زیانمنیږي."},{"en":"Response: However, digital collaboration tools have largely mitigated this concern.","ps":"ځواب: خو، رقمي همغږۍ وسایلو دا اندیښنه پراخه کچه کمه کړې ده."},{"en":"Conclusion: On balance, the evidence favors continued support for remote work policies.","ps":"پایله: په ټوليز ډول، شواهد د لرې کار پالیسیو دوامدارې ملاتړ ملاتړ کوي."},{"en":"Therefore, organizations should consider flexible work arrangements.","ps":"له همدې امله، سازمانونه باید د انعطاف وړ کاري تنظیماتو ته پام وکړي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Remote work is good because it is good. | Right: Remote work improves productivity, as evidenced by... | A claim must be supported by evidence, not restated as its own justification (circular reasoning).","ps":"ادعا باید د شواهدو سره ملاتړ شي، نه د ځان په توګه بیا بیانول (دوراني دلیل)."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-paraphrase-grammar","titleEn":"Paraphrase Grammar","titlePs":"د بیا بیانولو ګرامر","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"paraphrase-grammar","masteryConceptId":"grammar-concept-paraphrase-grammar","prerequisites":["grammar-d20-academic-argument-structure"],"wizardSessionId":"grammar-d20-academic-paraphrase-grammar-wiz","testSessionId":"grammar-d20-academic-paraphrase-grammar-test","blocks":[{"type":"explanation","titleEn":"Paraphrase Grammar","en":"Paraphrasing requires changing grammatical structure (active↔passive, clause↔phrase) and vocabulary, not just swapping a few words.","ps":"د بیا بیانولو لپاره باید ګرامري جوړښت (فعال↔مجهول، فقره↔جمله) او لغتونه بدل شي، نه یوازې څو کلمې."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Original: The researchers collected data over five years. Paraphrase: Over a five-year period, data was gathered by the research team.","ps":"اصلي: څیړونکو پنځه کاله معلومات راټول کړل. بیا بیانونه: د پنځه کلن دورې په اوږدو کې، معلومات د څیړنیز ټیم لخوا راټول شول."},{"en":"Original: Because prices rose, demand fell. Paraphrase: The rise in prices led to a decline in demand.","ps":"اصلي: ځکه چې بیې لوړې شوې، غوښتنه راټیټه شوه. بیا بیانونه: د بیو لوړوالي د غوښتنې د راټیټیدو لامل شو."},{"en":"Original: The study shows that exercise reduces stress. Paraphrase: According to the study, engaging in physical activity is associated with lower stress levels.","ps":"اصلي: مطالعه ښیي چې ورزش فشار کموي. بیا بیانونه: د مطالعې له مخې، فزیکي فعالیت له ټیټ فشار سره تړاو لري."},{"en":"Original: Many students find grammar difficult. Paraphrase: Grammar poses a challenge for a large number of learners.","ps":"اصلي: ډېری زده کوونکي ګرامر ستونزمن ګڼي. بیا بیانونه: ګرامر د زده کوونکو یوه لویه ډله ننګونه راولي."},{"en":"Original: The government reduced taxes to boost the economy. Paraphrase: In an effort to stimulate the economy, tax rates were lowered.","ps":"اصلي: حکومت اقتصاد د ودې لپاره مالیه راټیټه کړه. بیا بیانونه: د اقتصاد د هڅوونې هڅه کې، مالیاتي کچه راټیټه شوه."},{"en":"Original: This method saves time. Paraphrase: Time is saved through the use of this method.","ps":"اصلي: دا میتود وخت خوندي کوي. بیا بیانونه: د دې میتود کارولو له لارې وخت خوندي کیږي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The researchers collected information over five years. (only one word changed — not a true paraphrase) | Right: Over a five-year period, data was gathered by the research team. | Changing only one word without altering grammatical structure is not a genuine paraphrase and risks being flagged as insufficient rewording.","ps":"یوازې د یوې کلمې بدلول بشپړ بیا بیانونه نه دی."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-formal-presentation-language","titleEn":"Formal Presentation Language","titlePs":"رسمي وړاندیز ژبه","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"formal-presentation-language","masteryConceptId":"grammar-concept-formal-presentation-language","prerequisites":["grammar-d20-academic-paraphrase-grammar"],"wizardSessionId":"grammar-d20-academic-formal-presentation-language-wiz","testSessionId":"grammar-d20-academic-formal-presentation-language-test","blocks":[{"type":"explanation","titleEn":"Formal Presentation Language","en":"Formal spoken presentations use structuring phrases (I would like to begin by, turning now to, to conclude) to guide the audience.","ps":"رسمي شفاهي وړاندیزونه د جوړښت جملو (I would like to begin by, turning now to, to conclude) کاروي ترڅو غونډونکي لارښود شي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"I would like to begin by outlining the main objectives.","ps":"زه غواړم د اصلي موخو په بیانولو سره پیل وکړم."},{"en":"Turning now to the second point, let us consider the financial implications.","ps":"اوس دویمې ټکي ته اړو، راځئ چې مالي پایلو ته پام وکړو."},{"en":"To illustrate this, I would like to share an example.","ps":"د دې د روښانه کولو لپاره، زه غواړم یو بیلګه شریک کړم."},{"en":"Before I conclude, I want to address one important caveat.","ps":"مخکې تر دې چې پای ته ورسیږم، غواړم یو مهم ملاحظه ته اشاره وکړم."},{"en":"To summarize the key findings, let me highlight three points.","ps":"د مهمو موندنو د لنډیز لپاره، اجازه راکړئ درې ټکي روښانه کړم."},{"en":"Thank you for your attention; I welcome any questions.","ps":"ستاسو د پام څخه مننه؛ زه ستاسو د هرې پوښتنې هرکلی کوم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: So yeah, next thing is money stuff. | Right: Turning now to the second point, let us consider the financial implications. | Casual filler language undermines the formality expected in an academic presentation.","ps":"ناسموالی ژبه د اکادمیک وړاندیز رسمیت له منځه وړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-source-attribution","titleEn":"Source Attribution Structures","titlePs":"د سرچینې منسوب کولو جوړښتونه","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"source-attribution-structures","masteryConceptId":"grammar-concept-source-attribution-structures","prerequisites":["grammar-d20-academic-formal-presentation-language"],"wizardSessionId":"grammar-d20-academic-source-attribution-wiz","testSessionId":"grammar-d20-academic-source-attribution-test","blocks":[{"type":"explanation","titleEn":"Source Attribution Structures","en":"Attribute ideas to sources clearly using According to X, X states that, or in-text citation patterns (Author, Year).","ps":"نظرونه سرچینو ته په روښانه توګه منسوب کړئ د According to X, X states that، یا د متن دننه یادونې بڼو (لیکوال، کال) په کارولو سره."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"According to Ahmadi (2022), literacy rates have improved significantly.","ps":"د احمدي (۲۰۲۲) له مخې، د لوستلو کچه د پام وړ ښه شوې ده."},{"en":"As Karimi states, \"education is the foundation of development\" (2020, p. 45).","ps":"لکه چې کریمي وایي، \"زده کړه د پرمختګ بنسټ دی\" (۲۰۲۰، ۴۵ مخ)."},{"en":"This view is supported by several studies (Rahimi, 2019; Noori, 2021).","ps":"دا نظر د څو مطالعو لخوا ملاتړ کیږي (رحیمي، ۲۰۱۹؛ نوري، ۲۰۲۱)."},{"en":"Referring to the original research, Yousafi (2018) notes a similar trend.","ps":"اصلي څیړنې ته اشاره کوي، یوسفي (۲۰۱۸) ورته رجحان یادوي."},{"en":"Based on the findings of Hashimi (2023), the program was deemed successful.","ps":"د هاشمي (۲۰۲۳) موندنو پر بنسټ، پروګرام بریالی وګڼل شو."},{"en":"The data, as reported by the ministry, indicate steady growth.","ps":"معلومات، لکه چې وزارت راپور ورکړی، ثابته وده ښیي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Education is the foundation of development, Karimi 2020. | Right: As Karimi (2020) states, \"education is the foundation of development.\" | A direct quotation needs a clear attribution phrase and quotation marks, not a bare citation tacked onto the end.","ps":"مستقیم نقل قول واضح منسوبولو جمله او د نقل قول نښې غواړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-synthesis-comparison","titleEn":"Synthesis and Comparison Structures","titlePs":"د ترکیب او پرتلې جوړښتونه","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"synthesis-comparison-structures","masteryConceptId":"grammar-concept-synthesis-comparison-structures","prerequisites":["grammar-d20-academic-source-attribution"],"wizardSessionId":"grammar-d20-academic-synthesis-comparison-wiz","testSessionId":"grammar-d20-academic-synthesis-comparison-test","blocks":[{"type":"explanation","titleEn":"Synthesis and Comparison Structures","en":"Synthesize multiple sources using structures like both X and Y suggest, whereas X argues..., Y contends, and unlike X, Y found.","ps":"ډېری سرچینې د both X and Y suggest, whereas X argues..., Y contends، او unlike X, Y found جوړښتونو په مرسته یوځای کړئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Both Karimi (2020) and Noori (2021) suggest that funding is the key barrier.","ps":"دواړه کریمي (۲۰۲۰) او نوري (۲۰۲۱) وړاندیز کوي چې تمویل اصلي خنډ دی."},{"en":"Whereas Ahmadi argues for centralized reform, Rahimi contends that local solutions are more effective.","ps":"پداسې حال کې چې احمدي د مرکزي اصلاح ملاتړ کوي، رحیمي استدلال کوي چې محلي حلونه ډېر مؤثر دي."},{"en":"Unlike earlier studies, Yousafi's (2023) research found no significant correlation.","ps":"د مخکینیو مطالعو برخلاف، د یوسفي (۲۰۲۳) څیړنه هیڅ د پام وړ اړیکه ونه موندله."},{"en":"Taken together, these studies point to a consistent trend across regions.","ps":"دواړه یوځای، دا مطالعې د سیمو په اوږدو کې ثابته رجحان ته اشاره کوي."},{"en":"While the two theories differ in emphasis, both acknowledge the role of context.","ps":"که څه هم دواړه تیورۍ په ټینګار کې توپیر لري، دواړه د شرایطو رول مني."},{"en":"In contrast to the quantitative findings, the qualitative interviews revealed deeper concerns.","ps":"د کمي موندنو برخلاف، کیفي مرکو ژورو اندیښنو ښکاره کړې."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Karimi said X and Noori said Y and they are the same. | Right: Both Karimi (2020) and Noori (2021) suggest that funding is the key barrier. | Synthesis requires precise comparative language, not a vague and they are the same claim.","ps":"ترکیب دقیقه پرتلیزه ژبه غواړي، نه یو مبهم ادعا."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-concession-qualification","titleEn":"Concession and Qualification","titlePs":"منل او شرطي کول","levelNumber":null,"acceptedLevelId":"academic","branchId":"argumentation","subbranchId":"concession-and-qualification","masteryConceptId":"grammar-concept-concession-and-qualification","prerequisites":["grammar-d20-academic-synthesis-comparison"],"wizardSessionId":"grammar-d20-academic-concession-qualification-wiz","testSessionId":"grammar-d20-academic-concession-qualification-test","blocks":[{"type":"explanation","titleEn":"Concession and Qualification","en":"Concede a valid point from an opposing view (admittedly, granted, while it is true that) before qualifying it with your own position.","ps":"د مخالف نظر یوه سمه ټکی ومنئ (admittedly, granted, while it is true that) مخکې تر دې چې خپل دریځ سره یې شرطي کړئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Admittedly, the sample size was small; nevertheless, the results are suggestive.","ps":"باید ومنل شي، نمونه کوچنۍ وه؛ سره له دې هم، پایلې وړاندیز کوونکي دي."},{"en":"Granted, costs may rise initially, but long-term savings outweigh this concern.","ps":"ومنئ چې لګښتونه ممکن لومړی لوړ شي، خو اوږدمهاله خوندیتوب دې اندیښنې ته زیاته ارزښت لري."},{"en":"While it is true that remote work has drawbacks, the benefits generally outweigh them.","ps":"که څه هم رښتیا ده چې لرې کار زیانونه لري، ګټې معمولا ډېرې دي."},{"en":"Of course, no policy is without risk, yet inaction carries greater risk.","ps":"البته، هیڅ پالیسي پرته له خطره نه ده، خو بې عملي ډېر خطر لري."},{"en":"It must be acknowledged that exceptions exist, though the overall trend remains clear.","ps":"باید ومنل شي چې استثناوې شتون لري، که څه هم ټولیز رجحان روښانه پاتې کیږي."},{"en":"To be fair, critics raise legitimate concerns about implementation costs.","ps":"د انصاف لپاره، منتقدین د پلي کولو لګښتونو په اړه مشروع اندیښنې راپورته کوي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The sample was small, so the results are meaningless. | Right: Admittedly, the sample size was small; nevertheless, the results are suggestive. | Dismissing your own findings entirely undermines the argument — concession should be paired with a qualified defense, not surrender.","ps":"د خپلو موندنو بشپړ رد کول دلیل کمزوری کوي، منل باید د شرطي دفاع سره وي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-stance","titleEn":"Academic Stance","titlePs":"اکادمیک دریځ","levelNumber":null,"acceptedLevelId":"academic","branchId":"argumentation","subbranchId":"academic-stance","masteryConceptId":"grammar-concept-academic-stance","prerequisites":["grammar-d20-academic-concession-qualification"],"wizardSessionId":"grammar-d20-academic-stance-wiz","testSessionId":"grammar-d20-academic-stance-test","blocks":[{"type":"explanation","titleEn":"Academic Stance","en":"Express a clear scholarly position using phrases like this paper argues that, we contend, the present study demonstrates.","ps":"یو روښانه علمي دریځ د this paper argues that, we contend, the present study demonstrates جملو سره بیان کړئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"This paper argues that early intervention significantly improves outcomes.","ps":"دا مقاله دلیل وړاندي کوي چې وختي مداخله پایلې د پام وړ ښه کوي."},{"en":"We contend that the current framework is insufficient.","ps":"موږ استدلال کوو چې اوسنی چوکاټ ناکافي دی."},{"en":"The present study demonstrates a robust relationship between the two variables.","ps":"اوسنۍ مطالعه د دواړو متغیرونو ترمنځ یوه قوي اړیکه ښیي."},{"en":"This research takes the position that policy reform is overdue.","ps":"دا څیړنه دا دریځ نیسي چې د پالیسۍ اصلاح ډېره ناوخته شوې."},{"en":"It is the central claim of this paper that economic factors dominate the analysis.","ps":"د دې مقالې مرکزي ادعا دا ده چې اقتصادي فکتورونه پر تحلیل حاکم دي."},{"en":"This study challenges the prevailing assumption that size determines success.","ps":"دا مطالعه هغه غالب انګیرنه ننګوي چې اندازه بریالیتوب ټاکي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: I think maybe this could be sort of true. | Right: This paper argues that early intervention significantly improves outcomes. | Weak, hedging-heavy language undermines a clear scholarly stance — academic writing should state its position directly, even while allowing for calibrated certainty elsewhere.","ps":"ډېر کمزوری، له اندازې ډکه ژبه روښانه علمي دریځ کمزوری کوي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-cause-effect","titleEn":"Cause-Effect Structures","titlePs":"د لامل-پایلې جوړښتونه","levelNumber":null,"acceptedLevelId":"academic","branchId":"argumentation","subbranchId":"cause-effect-structures","masteryConceptId":"grammar-concept-cause-effect-structures","prerequisites":["grammar-d20-academic-stance"],"wizardSessionId":"grammar-d20-academic-cause-effect-wiz","testSessionId":"grammar-d20-academic-cause-effect-test","blocks":[{"type":"explanation","titleEn":"Cause-Effect Structures","en":"Express causal relationships precisely using structures like this leads to, results in, is attributable to, stems from — matching the strength of evidence.","ps":"د سببي اړیکو دقیق بیان لپاره د this leads to, results in, is attributable to, stems from جوړښتونه وکاروئ، د شواهدو د کچې سره سم."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Poor infrastructure results in higher transportation costs.","ps":"کمزوری زیربنا لوړ ترانسپورت لګښتونو لامل کیږي."},{"en":"The decline in enrollment is attributable to economic hardship.","ps":"د ثبت نام راکمېدو اقتصادي ستونزو ته منسوب دی."},{"en":"This delay stems from insufficient staffing.","ps":"دا ځنډ د ناکافي کارکوونکو څخه سرچینه اخلي."},{"en":"Increased investment leads to improved outcomes.","ps":"زیات پانګونه ښو پایلو ته وړي."},{"en":"The shortage can be traced back to disrupted supply chains.","ps":"کمښت د خنډ شویو عرضې زنځیرونو ته ورګرځول کیدی شي."},{"en":"These findings, taken together, point to a systemic cause rather than an isolated incident.","ps":"دا موندنې، په ټولیز ډول، یو سیستمي لامل ته اشاره کوي نه د یو جلا پیښ."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: X happened, then Y happened, so X caused Y. | Right: The relationship between X and Y warrants further investigation before a causal claim can be made. | Sequence alone (correlation) does not prove causation — academic writing must distinguish between the two.","ps":"یوازې د پیښیدو ترتیب سببیت نه ثابتوي، اکادمیک لیکنه باید دواړه بېل کړي."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-avoiding-overclaiming","titleEn":"Avoiding Overclaiming","titlePs":"د زیاتو ادعاوو ډډه کول","levelNumber":null,"acceptedLevelId":"academic","branchId":"argumentation","subbranchId":"avoiding-overclaiming","masteryConceptId":"grammar-concept-avoiding-overclaiming","prerequisites":["grammar-d20-academic-cause-effect"],"wizardSessionId":"grammar-d20-academic-avoiding-overclaiming-wiz","testSessionId":"grammar-d20-academic-avoiding-overclaiming-test","blocks":[{"type":"explanation","titleEn":"Avoiding Overclaiming","en":"Limit claims to what the evidence supports; acknowledge limitations (this study is limited to, findings may not generalize to) rather than overstating scope.","ps":"ادعاوې د شواهدو ملاتړ سره محدودې کړئ؛ محدودیتونه ومنئ (this study is limited to, findings may not generalize to) پرځای د ساحې لوړوالي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"This study is limited to urban populations and may not generalize to rural areas.","ps":"دا مطالعه ښاري نفوسو پورې محدوده ده او ممکن کلیوالو سیمو ته عمومي نشي."},{"en":"These findings should be interpreted with caution given the small sample size.","ps":"دا موندنې باید د کوچنۍ نمونې کچې په پام کې نیولو سره احتیاط سره تشریح شي."},{"en":"The results do not establish causation but suggest an association worth investigating.","ps":"پایلې سببیت نه ثابتوي خو یوه اړیکه وړاندیز کوي چې د پلټنې وړ ده."},{"en":"Further research is needed before firm conclusions can be drawn.","ps":"د قطعي پایلو د اخیستلو مخکې نور تحقیق ته اړتیا ده."},{"en":"While promising, these results represent a single case study rather than a broad trend.","ps":"که څه هم امیدوونکي دي، دا پایلې یو واحد قضیه مطالعه استازیتوب کوي نه یو پراخ رجحان."},{"en":"The findings apply specifically to the conditions tested and may not hold elsewhere.","ps":"موندنې ځانګړي هغو شرایطو پورې اړوندې دي چې ازمویل شوي، ممکن نورو ځایونو کې پلي نشي."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: This proves that the method always works everywhere. | Right: These findings suggest that the method may be effective under the tested conditions. | A single study almost never proves universal, unconditional effectiveness — claims must be bounded by the actual scope of the evidence.","ps":"یوه واحده مطالعه نادره وخت نړیواله اغیزمنتوب ثابتوي، ادعاوې باید د شواهدو ریښتینې ساحې سره سمون ولري."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-formal-qa-responses","titleEn":"Complex Formal Question-and-Answer Responses","titlePs":"پیچلي رسمي پوښتنه-ځواب ځوابونه","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"complex-formal-question-answer-responses","masteryConceptId":"grammar-concept-complex-formal-question-answer-responses","prerequisites":["grammar-d20-academic-avoiding-overclaiming"],"wizardSessionId":"grammar-d20-academic-formal-qa-responses-wiz","testSessionId":"grammar-d20-academic-formal-qa-responses-test","blocks":[{"type":"explanation","titleEn":"Complex Formal Question-and-Answer Responses","en":"Formal Q&A responses (in academic defenses, interviews, presentations) restate the question, address it directly, and provide supporting reasoning.","ps":"رسمي پوښتنه-ځواب ځوابونه (اکادمیک دفاع، مرکې، وړاندیزونه) پوښتنه بیا بیانوي، مستقیم ورته ځواب ورکوي، او ملاتړ استدلال وړاندې کوي."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"That's an important question. To address why enrollment declined, I would point to three factors.","ps":"دا یوه مهمه پوښتنه ده. د دې د ځوابولو لپاره چې ولې ثبت نام راټیټ شو، زه درې فکتورونو ته اشاره کوم."},{"en":"You raise a fair point about the sample size; let me clarify how we addressed that limitation.","ps":"ته د نمونې کچې په اړه یو منصفانه ټکی راپورته کوې؛ اجازه راکړئ روښانه کړم چې څنګه مو دا محدودیت حل کړ."},{"en":"If I understand the question correctly, you are asking whether the results are replicable.","ps":"که پوښتنه سمه پوهیږم، ته پوښتې چې آیا پایلې بیا تکراریدونکې دي."},{"en":"That is a fair criticism, and I would respond by noting that...","ps":"دا یوه منصفانه نیوکه ده، او زه به یې ځواب داسې ورکړم چې..."},{"en":"To directly answer your question: yes, the effect held across all subgroups.","ps":"ستا پوښتنې ته مستقیم ځواب: هو، اغیز په ټولو فرعي ډلو کې پاتې شو."},{"en":"Let me address that concern by walking through the methodology in more detail.","ps":"اجازه راکړئ دا اندیښنه د میتودولوژۍ د نورو تفصیلاتو له لارې حل کړم."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: Umm, I don't know, maybe, whatever. | Right: That is a fair question — let me explain how we addressed it. | Formal academic Q&A requires a structured, substantive response even when uncertainty exists — acknowledge limits precisely rather than dismissing the question.","ps":"رسمي اکادمیک پوښتنه-ځواب یو منظم، مهم ځواب غواړي حتی که عدم ډاډ شتون ولري."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}},{"id":"grammar-d20-academic-formal-reformulation-precision","titleEn":"Formal Reformulation and Precision","titlePs":"رسمي بیا جوړونه او دقت","levelNumber":null,"acceptedLevelId":"academic","branchId":"academic-style","subbranchId":"formal-reformulation-and-precision","masteryConceptId":"grammar-concept-formal-reformulation-and-precision","prerequisites":["grammar-d20-academic-formal-qa-responses"],"wizardSessionId":"grammar-d20-academic-formal-reformulation-precision-wiz","testSessionId":"grammar-d20-academic-formal-reformulation-precision-test","blocks":[{"type":"explanation","titleEn":"Formal Reformulation and Precision","en":"Reformulate loosely worded ideas with precise academic vocabulary, avoiding vague quantifiers (a lot, stuff, things) in favor of exact terms.","ps":"ازادانه بیان شوي نظرونه د دقیقو اکادمیک لغتونو سره بیا جوړ کړئ، د مبهمو اندازو کلماتو (a lot, stuff, things) پرځای دقیق اصطلاحات وکاروئ."},{"type":"examples","titleEn":"Examples","titlePs":"مثالونه","items":[{"en":"Loose: There were a lot of problems. Precise: Numerous structural deficiencies were identified.","ps":"ازاد: ډېرې ستونزې وې. دقیق: ډېرې جوړښتي کمښتونه وپیژندل شول."},{"en":"Loose: The study looked at stuff about kids. Precise: The study examined developmental outcomes among children.","ps":"ازاد: مطالعې د ماشومانو په اړه شیان وکتل. دقیق: مطالعې د ماشومانو ترمنځ وده پایلې وڅیړلې."},{"en":"Loose: Things got worse over time. Precise: Conditions deteriorated progressively over the study period.","ps":"ازاد: شیان په وخت سره خرابیدل. دقیق: شرایط د مطالعې د دورې په اوږدو کې تدریجا خراب شول."},{"en":"Loose: Basically, the plan didn't work. Precise: The intervention failed to achieve its stated objectives.","ps":"ازاد: اساسا، پلان ونه شو. دقیق: مداخله خپلو ټاکل شویو موخو ته ونشوای رسیدلی."},{"en":"Loose: A ton of people were affected. Precise: A substantial proportion of the population was affected.","ps":"ازاد: ډېری خلک اغیزمن شول. دقیق: د نفوس د پام وړ برخه اغیزمنه شوه."},{"en":"Loose: It was kind of important. Precise: It was a significant contributing factor.","ps":"ازاد: یو څه مهم و. دقیق: دا یو مهم مرستندوی فکتور و."}]},{"type":"note","titleEn":"Common Errors","en":"Wrong: The study found a bunch of stuff that was kind of interesting. | Right: The study identified several noteworthy patterns. | Vague quantifiers and filler words (a bunch of stuff, kind of) are inappropriate in formal academic register — replace with precise, measured language.","ps":"مبهم اندازې کلمات د رسمي اکادمیک ژبې لپاره ناسم دي، د دقیقو کلماتو سره یې بدل کړئ."}],"officialCandidateEligible":true,"officialCurriculumEligible":false,"ownerApprovalStatus":"pending-owner-review","translationStatus":"phase-reviewed-unverified","provenance":{"sourceType":"academy-authored","externalSource":"","permissionStatus":"not-applicable-original-content"}}];

